CREATE OR REPLACE FUNCTION public.acknowledge_delivery(p_entity uuid, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; result jsonb;
begin
  ws:=public.require_entity(p_entity);
  perform 1 from public.delivery_challans where id=p_id and workspace_id=ws and entity_id=p_entity and status='issued' for update;
  if not found then raise exception 'An issued challan is required' using errcode='23514'; end if;
  insert into public.delivery_acknowledgements(workspace_id,entity_id,dc_id,received_by,received_at,notes,recorded_by)
    values(ws,p_entity,p_id,p_data->>'receivedBy',(p_data->>'receivedAt')::timestamptz,p_data->>'notes',auth.uid())
    on conflict(dc_id) do nothing;
  return public.challan_payload(p_id);
end $function$

CREATE OR REPLACE FUNCTION public.allocate_document_number(p_entity uuid, p_type text, p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.billing_entities; ws uuid; start_year integer; starts date; ends date; period text; prefix text; serial bigint;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict e from public.billing_entities where id=p_entity;
  if p_type not in ('invoice','delivery_challan') then raise exception 'Invalid document type'; end if;
  prefix:=case when p_type='invoice' then coalesce(nullif(btrim(e.invoice_prefix),''),e.entity_code)
    else coalesce(nullif(btrim(e.dc_prefix),''),e.entity_code||'/DC') end;
  if e.numbering_mode='continuous' then period:='CONTINUOUS';
  else
    start_year:=extract(year from p_date)::integer-case when extract(month from p_date)<e.financial_year_start_month then 1 else 0 end;
    starts:=make_date(start_year,e.financial_year_start_month,1);ends:=(starts+interval '1 year'-interval '1 day')::date;
    period:=right(start_year::text,2)||'-'||right((start_year+1)::text,2);
  end if;
  insert into public.document_sequences(workspace_id,entity_id,document_type,period_key,period_start,period_end)
    values(ws,p_entity,p_type,period,starts,ends) on conflict do nothing;
  update public.document_sequences set next_number=next_number+1,updated_at=now()
    where workspace_id=ws and entity_id=p_entity and document_type=p_type and period_key=period returning next_number-1 into serial;
  return jsonb_build_object('number',prefix||'/'||case when period='CONTINUOUS' then '' else period||'/' end||lpad(serial::text,greatest(4,length(serial::text)),'0'),
    'period',period,'sequence',serial,'prefix',prefix,'mode',e.numbering_mode,'start',starts,'end',ends);
end $function$

CREATE OR REPLACE FUNCTION public.archive_directory_record(p_entity uuid, p_table text, p_id uuid, p_version bigint, p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; result jsonb; current_version bigint;
begin
  ws:=public.require_entity(p_entity);
  if p_table='billing_entities' and p_id=p_entity then
    select version into current_version from public.billing_entities where id=p_id and workspace_id=ws for update;
    if current_version is distinct from p_version then raise exception 'Company changed. Reload it.' using errcode='40001'; end if;
    update public.billing_entities set is_active=p_active where id=p_id returning to_jsonb(billing_entities.*) into result;
  elsif p_table='customers' then
    select version into current_version from public.customers where id=p_id and workspace_id=ws and entity_id=p_entity for update;
    if current_version is null then raise exception 'Customer not found' using errcode='P0002'; end if;
    if current_version<>p_version then raise exception 'Customer changed. Reload it.' using errcode='40001'; end if;
    update public.customers set is_active=p_active where id=p_id returning to_jsonb(customers.*) into result;
  else raise exception 'Invalid directory operation' using errcode='23514'; end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.cancel_challan(p_entity uuid, p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; d public.delivery_challans;
begin
  ws:=public.require_entity(p_entity);
  select * into strict d from public.delivery_challans where id=p_id and entity_id=p_entity and workspace_id=ws for update;
  if d.status='cancelled' then return public.challan_payload(p_id); end if;
  if d.status<>'issued' or coalesce(length(btrim(p_reason)),0)=0 then raise exception 'Enter a reason for cancelling an issued challan' using errcode='23514'; end if;
  update public.delivery_challans set status='cancelled',cancelled_at=clock_timestamp(),cancelled_by=auth.uid(),cancel_reason=btrim(p_reason) where id=p_id;
  insert into public.document_files(workspace_id,entity_id,dc_id,template_id,variant) values(ws,p_entity,p_id,d.template_id,'cancelled');
  return public.challan_payload(p_id);
end $function$

CREATE OR REPLACE FUNCTION public.cancel_invoice(p_entity uuid, p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; inv public.invoices;
begin
  ws:=public.require_entity(p_entity);
  select * into strict inv from public.invoices where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  if inv.status='cancelled' then return public.invoice_payload(p_id); end if;
  if inv.status<>'issued' or coalesce(length(btrim(p_reason)),0)=0 then raise exception 'An issued invoice and cancellation reason are required' using errcode='23514'; end if;
  if exists(select 1 from public.payments where invoice_id=p_id and status='posted') then raise exception 'Reverse receipts before cancelling' using errcode='23514'; end if;
  update public.invoices set status='cancelled',cancelled_at=clock_timestamp(),cancelled_by=auth.uid(),cancel_reason=btrim(p_reason) where id=p_id;
  insert into public.document_files(workspace_id,entity_id,invoice_id,template_id,variant) values(ws,p_entity,p_id,inv.template_id,'cancelled');
  return public.invoice_payload(p_id);
end $function$

CREATE OR REPLACE FUNCTION public.claim_document_file(p_entity uuid, p_type text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; file public.document_files; variant_value text; state text;
begin
  ws:=public.require_entity(p_entity);
  if p_type='invoice' then select status into state from public.invoices where id=p_id and entity_id=p_entity and workspace_id=ws for share;
  elsif p_type='delivery_challan' then select status into state from public.delivery_challans where id=p_id and entity_id=p_entity and workspace_id=ws for share;
  else raise exception 'Invalid document type' using errcode='23514'; end if;
  if state is null or state='draft' then raise exception 'Issue the document before generating a PDF' using errcode='23514'; end if;
  variant_value:=case when state='cancelled' then 'cancelled' else 'original' end;
  select * into strict file from public.document_files where entity_id=p_entity and variant=variant_value
    and (case when p_type='invoice' then invoice_id=p_id else dc_id=p_id end) for update;
  if file.status='ready' then return to_jsonb(file); end if;
  if file.status='processing' and file.lease_expires_at>clock_timestamp() then raise exception 'PDF generation is already running. Retry shortly.' using errcode='55P03'; end if;
  update public.document_files set status='processing',attempt_count=attempt_count+1,claim_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '2 minutes',updated_at=now()
    where id=file.id returning * into file;
  return to_jsonb(file);
end $function$

CREATE OR REPLACE FUNCTION public.claim_report_export(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.report_exports;
begin
  select r.* into strict result from public.report_exports r join public.workspaces w on w.id=r.workspace_id where r.id=p_id and w.owner_user_id=auth.uid() for update of r;
  if result.expires_at<clock_timestamp() then raise exception 'Export expired. Request a new report.' using errcode='23514'; end if;
  if result.status='ready' then return to_jsonb(result); end if;
  if result.status='processing' and result.lease_expires_at>clock_timestamp() then raise exception 'Export is being generated' using errcode='55P03'; end if;
  update public.report_exports set status='processing',attempt_count=attempt_count+1,claim_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '2 minutes'
    where id=p_id returning * into result;
  return to_jsonb(result);
end $function$

CREATE OR REPLACE FUNCTION public.configure_catalog(p_entity uuid, p_table text, p_id uuid, p_version bigint, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; result jsonb; oldrow jsonb; record_id uuid:=coalesce(p_id,gen_random_uuid());
begin
  ws:=public.require_entity(p_entity,true);
  if p_table not in ('styles','print_types','placements','units','tax_profiles') then raise exception 'Unknown catalog' using errcode='23514'; end if;
  if p_id is not null then
    execute format('select to_jsonb(r) from public.%I r where id=$1 and workspace_id=$2 and entity_id=$3 for update',p_table)
      into oldrow using p_id,ws,p_entity;
    if oldrow is null then raise exception 'Catalog record not found' using errcode='P0002'; end if;
    if p_version is null or p_version<>(oldrow->>'version')::bigint then raise exception 'Catalog record changed. Reload it.' using errcode='40001'; end if;
  end if;
  if p_table='styles' then
    if p_id is null then raise exception 'Use style resolution to create a style' using errcode='23514'; end if;
    update public.styles set
      name=case when p_data ? 'name' then p_data->>'name' else name end,
      description=case when p_data ? 'description' then p_data->>'description' else description end,
      default_print_type_id=case when p_data ? 'defaultPrintTypeId' then (p_data->>'defaultPrintTypeId')::uuid else default_print_type_id end,
      default_placement_id=case when p_data ? 'defaultPlacementId' then (p_data->>'defaultPlacementId')::uuid else default_placement_id end,
      default_unit_id=case when p_data ? 'defaultUnitId' then (p_data->>'defaultUnitId')::uuid else default_unit_id end,
      is_active=coalesce((p_data->>'is_active')::boolean,is_active) where id=p_id returning to_jsonb(styles.*) into result;
  elsif p_table='tax_profiles' then
    if p_id is null then
      insert into public.tax_profiles(id,workspace_id,entity_id,name,tax_mode,cgst_rate,sgst_rate,igst_rate,other_tax_rate)
        values(record_id,ws,p_entity,p_data->>'name',p_data->>'tax_mode',coalesce((p_data->>'cgst_rate')::numeric,0),
        coalesce((p_data->>'sgst_rate')::numeric,0),coalesce((p_data->>'igst_rate')::numeric,0),coalesce((p_data->>'other_tax_rate')::numeric,0))
        returning to_jsonb(tax_profiles.*) into result;
    else
      update public.tax_profiles set name=coalesce(p_data->>'name',name),tax_mode=coalesce(p_data->>'tax_mode',tax_mode),
        cgst_rate=coalesce((p_data->>'cgst_rate')::numeric,cgst_rate),sgst_rate=coalesce((p_data->>'sgst_rate')::numeric,sgst_rate),
        igst_rate=coalesce((p_data->>'igst_rate')::numeric,igst_rate),other_tax_rate=coalesce((p_data->>'other_tax_rate')::numeric,other_tax_rate),
        is_active=coalesce((p_data->>'is_active')::boolean,is_active) where id=p_id returning to_jsonb(tax_profiles.*) into result;
    end if;
  elsif p_id is null then
    execute format('insert into public.%I(id,workspace_id,entity_id,code,label,sort_order) values($1,$2,$3,$4,$5,$6) returning to_jsonb(%I.*)',p_table,p_table)
      into result using record_id,ws,p_entity,upper(btrim(p_data->>'code')),btrim(p_data->>'label'),coalesce((p_data->>'sort_order')::integer,0);
  else
    execute format('update public.%I set label=coalesce($1,label),is_active=coalesce($2,is_active),sort_order=coalesce($3,sort_order) where id=$4 returning to_jsonb(%I.*)',p_table,p_table)
      into result using p_data->>'label',(p_data->>'is_active')::boolean,(p_data->>'sort_order')::integer,p_id;
  end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.configure_entity(p_entity uuid, p_version bigint, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; e public.billing_entities;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict e from public.billing_entities where id=p_entity for update;
  if e.version<>p_version then raise exception 'Company settings changed' using errcode='40001'; end if;
  update public.billing_entities set
    default_tax_profile_id=case when p_data ? 'defaultTaxProfileId' then (p_data->>'defaultTaxProfileId')::uuid else default_tax_profile_id end,
    default_invoice_template_id=case when p_data ? 'defaultInvoiceTemplateId' then (p_data->>'defaultInvoiceTemplateId')::uuid else default_invoice_template_id end,
    default_dc_template_id=case when p_data ? 'defaultDcTemplateId' then (p_data->>'defaultDcTemplateId')::uuid else default_dc_template_id end,
    rounding_increment=coalesce((p_data->>'roundingIncrement')::numeric,rounding_increment),
    default_terms=case when p_data ? 'defaultTerms' then p_data->>'defaultTerms' else default_terms end
    where id=p_entity returning * into e;
  if e.default_tax_profile_id is not null and not exists(select 1 from public.tax_profiles where id=e.default_tax_profile_id and is_active) then
    raise exception 'Default tax profile is archived' using errcode='23514';
  end if;
  return to_jsonb(e);
end $function$

CREATE OR REPLACE FUNCTION public.customer_summary(p_entity uuid, p_customer uuid, p_from date, p_as_of date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; customer jsonb;
begin
  ws:=public.authorize_report_entities(array[p_entity]);
  select to_jsonb(c) into customer from public.customers c where id=p_customer and workspace_id=ws and entity_id=p_entity;
  if customer is null then raise exception 'Customer not found' using errcode='P0002'; end if;
  return jsonb_build_object('customer',customer,'summary',public.dashboard_data(array[p_entity],p_from,p_as_of,now(),p_customer));
end $function$

CREATE OR REPLACE FUNCTION public.delete_challan_draft(p_entity uuid, p_id uuid, p_version bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; d public.delivery_challans;
begin
  ws:=public.require_entity(p_entity);
  select * into strict d from public.delivery_challans where id=p_id and entity_id=p_entity and workspace_id=ws for update;
  if d.status<>'draft' or d.version<>p_version then raise exception 'Draft changed or already issued' using errcode='40001'; end if;
  delete from public.dc_items where dc_id=p_id;
  delete from public.delivery_challans where id=p_id;
end $function$

CREATE OR REPLACE FUNCTION public.delete_invoice_draft(p_entity uuid, p_id uuid, p_version bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; inv public.invoices;
begin
  ws:=public.require_entity(p_entity);
  select * into strict inv from public.invoices where id=p_id and entity_id=p_entity and workspace_id=ws for update;
  if inv.status<>'draft' or inv.version<>p_version then raise exception 'Draft changed or already issued' using errcode='23514'; end if;
  delete from public.invoice_items where invoice_id=p_id;
  delete from public.invoices where id=p_id;
end $function$

CREATE OR REPLACE FUNCTION public.document_detail(p_entity uuid, p_kind text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; result jsonb;
begin
  ws:=public.authorize_report_entities(array[p_entity]);
  if p_kind='invoices' then
    if exists(select 1 from public.invoices where id=p_id and workspace_id=ws and entity_id=p_entity) then result:=public.invoice_payload(p_id); end if;
  elsif p_kind='challans' then
    if exists(select 1 from public.delivery_challans where id=p_id and workspace_id=ws and entity_id=p_entity) then result:=public.challan_payload(p_id); end if;
  else raise exception 'Invalid document type' using errcode='23514'; end if;
  if result is null then raise exception 'Document not found' using errcode='P0002'; end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.duplicate_invoice(p_entity uuid, p_id uuid, p_new_id uuid, p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; source public.invoices; payload jsonb; lines jsonb; result jsonb;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict source from public.invoices where id=p_id and entity_id=p_entity and workspace_id=ws for share;
  select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',i.sort_order,'description',i.particulars,
    'quantity',i.quantity::text,'rate',i.unit_rate::text,'style',i.style_number_snapshot,'printType',i.print_type_snapshot,
    'placement',i.placement_snapshot,'unitCode',u.code,'placementDetail',i.placement_detail,'hsnSacCode',i.hsn_sac_code,
    'discountCents',i.line_discount_amount*100,'adjustmentCents',i.line_adjustment_amount*100,'adjustmentReason',i.line_adjustment_reason,
    'taxProfileId',i.tax_profile_id)) order by i.sort_order) into lines
    from public.invoice_items i join public.units u on u.id=i.unit_id where i.invoice_id=p_id;
  payload:=jsonb_strip_nulls(jsonb_build_object('id',p_new_id,'customerId',source.customer_id,'date',p_date,
    'due',p_date+greatest(source.due_date-source.invoice_date,0),'reference',source.reference_number,'notes',source.notes,'terms',source.terms,
    'discountCents',source.invoice_discount_total*100,'lines',lines));
  if not exists(select 1 from public.invoice_items where invoice_id=p_id and tax_profile_id is not null) then
    payload:=payload||jsonb_build_object('taxBasisPoints',coalesce((select max(other_tax_rate)*100 from public.invoice_items where invoice_id=p_id),0));
  end if;
  result:=public.save_invoice_draft(p_entity,payload);
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.filtered_report_data(p_entities uuid[], p_type text, p_from date, p_as_of date, p_recorded_through timestamp with time zone DEFAULT now(), p_customer uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; zone text; boundary timestamptz; headers jsonb; rows jsonb; summary jsonb;
begin
  ws:=public.authorize_report_entities(p_entities);
  select timezone into zone from public.workspaces where id=ws;
  if p_from is null or p_as_of is null or p_from>p_as_of or p_as_of-p_from>3660 or p_recorded_through is null or p_recorded_through>clock_timestamp() then
    raise exception 'Use a valid report period up to ten years' using errcode='23514';
  end if;
  if p_customer is not null and not exists(select 1 from public.customers where id=p_customer and workspace_id=ws and entity_id=any(p_entities)) then
    raise exception 'Customer not found' using errcode='42501';
  end if;
  boundary:=(p_as_of+1)::timestamp at time zone zone;
  if p_type in ('customers','companies') then
    summary:=public.dashboard_data(p_entities,p_from,p_as_of,p_recorded_through,p_customer);
    if p_type='companies' then
      headers:='["Company","Billed","Collected","Outstanding","Invoice count"]';
      select coalesce(jsonb_agg(jsonb_build_array(x->>'name',(x->>'billed')::numeric,(x->>'collected')::numeric,
        (x->>'outstanding')::numeric,(x->>'invoiceCount')::bigint)),'[]') into rows from jsonb_array_elements(summary->'entities') x;
    else
      headers:='["Company","Customer","Invoice count","Billed","Collected","Outstanding","Latest invoice"]';
      with eligible as (
        select b.*,coalesce((select sum(p.amount) from public.payments p where p.invoice_id=b.id and p.payment_date<=p_as_of and p.posted_at<=p_recorded_through
          and not coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false)),0) paid
        from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and b.invoice_date<=p_as_of and b.issued_at<=p_recorded_through
          and (p_customer is null or b.customer_id=p_customer) and not coalesce(b.cancelled_at<boundary and b.cancelled_at<=p_recorded_through,false)
      ), customers as (
        select b.entity_id,b.customer_id,max(b.seller_snapshot->>'legal_name') company,max(b.customer_snapshot->>'legal_name') customer,
          count(*) filter(where b.invoice_date>=p_from) n,coalesce(sum(b.grand_total) filter(where b.invoice_date>=p_from),0) billed,
          sum(b.grand_total-b.paid) outstanding,max(b.invoice_date) latest from eligible b group by b.entity_id,b.customer_id
      ) select coalesce(jsonb_agg(jsonb_build_array(c.company,c.customer,c.n,c.billed,
        coalesce((select sum(p.amount) from public.payments p join public.invoices b on b.id=p.invoice_id
          where b.entity_id=c.entity_id and b.customer_id=c.customer_id and p.payment_date between p_from and p_as_of and p.posted_at<=p_recorded_through
            and not coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false)),0),c.outstanding,c.latest)
        order by c.billed desc,c.entity_id,c.customer_id),'[]') into rows from customers c;
    end if;
    return jsonb_build_object('headers',headers,'rows',rows,'from',p_from,'asOf',p_as_of,'recordedThrough',p_recorded_through,
      'timezone',zone,'definitionVersion','v2','customerId',p_customer);
  end if;
  if p_type='challans' then
    headers:='["Challan","Recipient","Date","Items"]';
    select coalesce(jsonb_agg(jsonb_build_array(d.document_number,d.recipient_name,d.dc_date,
      (select string_agg(i.particulars,', ' order by i.sort_order) from public.dc_items i where i.dc_id=d.id)) order by d.dc_date,d.id),'[]') into rows
    from public.delivery_challans d where d.workspace_id=ws and d.entity_id=any(p_entities) and (p_customer is null or d.customer_id=p_customer) and d.dc_date between p_from and p_as_of
      and d.issued_at<=p_recorded_through and not(coalesce(d.cancelled_at<boundary and d.cancelled_at<=p_recorded_through,false));
  elsif p_type='cancelled' then
    headers:='["Bill","Customer","Cancelled on","Reason","Original amount"]';
    select coalesce(jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.cancelled_at,b.cancel_reason,b.grand_total) order by b.cancelled_at,b.id),'[]') into rows
    from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and (p_customer is null or b.customer_id=p_customer) and b.cancelled_at<=p_recorded_through
      and (b.cancelled_at at time zone zone)::date between p_from and p_as_of;
  elsif p_type='collections' then
    headers:='["Bill","Date","Method","Amount"]';
    select coalesce(jsonb_agg(jsonb_build_array(b.document_number,p.payment_date,p.method,p.amount) order by p.payment_date,p.id),'[]') into rows
    from public.payments p join public.invoices b on b.id=p.invoice_id
    where p.workspace_id=ws and p.entity_id=any(p_entities) and (p_customer is null or b.customer_id=p_customer) and p.payment_date between p_from and p_as_of
      and p.posted_at<=p_recorded_through and not(coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false));
  elsif p_type in ('billing','outstanding','customers','monthly','print-type','companies') then
    with eligible as (
      select b.*,
        coalesce((select sum(p.amount) from public.payments p where p.invoice_id=b.id and p.payment_date<=p_as_of and p.posted_at<=p_recorded_through
          and not(coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false))),0) paid
      from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and (p_customer is null or b.customer_id=p_customer) and b.invoice_date<=p_as_of and b.issued_at<=p_recorded_through
        and not(coalesce(b.cancelled_at<boundary and b.cancelled_at<=p_recorded_through,false))
    ), grouped as (
      select case when p_type='customers' then b.entity_id::text||':'||b.customer_id::text when p_type='monthly' then to_char(b.invoice_date,'YYYY-MM')
        else b.entity_id::text end grouping_key,
        min(case when p_type='customers' then (b.seller_snapshot->>'legal_name')||' · '||(b.customer_snapshot->>'legal_name')
          when p_type='monthly' then to_char(b.invoice_date,'YYYY-MM') else b.seller_snapshot->>'legal_name' end) label,
        sum(b.grand_total) total
      from eligible b where b.invoice_date>=p_from group by 1
    ), print_groups as (
      select coalesce(i.print_type_snapshot,'Unspecified') label,sum(i.line_total) total
        from eligible b join public.invoice_items i on i.invoice_id=b.id where b.invoice_date>=p_from group by 1
      union all
      select 'Round off',sum(b.round_off) from eligible b where b.invoice_date>=p_from having sum(b.round_off)<>0
    )
    select case when p_type='billing' then coalesce((select jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.invoice_date,b.grand_total) order by b.invoice_date,b.id) from eligible b where b.invoice_date>=p_from),'[]')
      when p_type='outstanding' then coalesce((select jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.due_date,b.grand_total-b.paid) order by b.due_date,b.id) from eligible b where b.grand_total>b.paid),'[]')
      when p_type='print-type' then coalesce((select jsonb_agg(jsonb_build_array(label,total) order by label) from print_groups),'[]')
      else coalesce((select jsonb_agg(jsonb_build_array(label,total) order by label) from grouped),'[]') end into rows;
    headers:=case when p_type='billing' then '["Bill","Customer","Date","Amount"]'::jsonb
      when p_type='outstanding' then '["Bill","Customer","Due date","Outstanding"]'::jsonb
      else '["Group","Amount"]'::jsonb end;
  else raise exception 'Unknown report' using errcode='23514'; end if;
  return jsonb_build_object('headers',headers,'rows',rows,'from',p_from,'asOf',p_as_of,'recordedThrough',p_recorded_through,'timezone',zone,'definitionVersion','v2','customerId',p_customer);
end $function$

CREATE OR REPLACE FUNCTION public.finish_document_file(p_entity uuid, p_id uuid, p_token uuid, p_result jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; prefix text;
begin
  ws:=public.require_entity(p_entity);prefix:=ws::text||'/'||p_entity::text||'/';
  if p_result ? 'path' and left(p_result->>'path',length(prefix))<>prefix then raise exception 'Invalid storage path' using errcode='42501'; end if;
  if not(p_result ? 'error') and (p_result->>'sha256' is null or p_result->>'sha256' !~ '^[0-9a-f]{64}$') then raise exception 'Invalid file checksum' using errcode='23514'; end if;
  update public.document_files set status=case when p_result ? 'error' then 'failed' else 'ready' end,
    object_path=p_result->>'path',sha256=p_result->>'sha256',byte_size=(p_result->>'size')::bigint,
    last_error=left(p_result->>'error',2000),generated_at=case when not(p_result ? 'error') then clock_timestamp() end,
    lease_expires_at=null,updated_at=now() where id=p_id and workspace_id=ws and entity_id=p_entity and claim_token=p_token
      and status='processing' and lease_expires_at>clock_timestamp();
  if not found then raise exception 'PDF claim expired' using errcode='40001'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.finish_report_export(p_id uuid, p_token uuid, p_result jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; first_entity uuid;
begin
  select r.workspace_id,r.entity_ids[1] into ws,first_entity from public.report_exports r join public.workspaces w on w.id=r.workspace_id where r.id=p_id and w.owner_user_id=auth.uid();
  if ws is null or (p_result ? 'path' and p_result->>'path' not like ws::text||'/'||first_entity::text||'/%') then raise exception 'Invalid export' using errcode='42501'; end if;
  update public.report_exports set status=case when p_result ? 'error' then 'failed' else 'ready' end,
    object_path=p_result->>'path',sha256=p_result->>'sha256',byte_size=(p_result->>'size')::bigint,
    last_error=p_result->>'error',generated_at=case when not(p_result ? 'error') then clock_timestamp() end,lease_expires_at=null,updated_at=now()
    where id=p_id and status='processing' and claim_token=p_token;
  if not found then raise exception 'Export claim expired' using errcode='40001'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.freeze_invoice_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare seller public.billing_entities; buyer public.customers;
begin
  if old.status='draft' and new.status='issued' then
    select * into strict seller from public.billing_entities where id=new.entity_id;
    select * into strict buyer from public.customers where id=new.customer_id;
    new.seller_snapshot:=to_jsonb(seller)||coalesce(new.payment_details_snapshot,'{}');
    new.customer_snapshot:=to_jsonb(buyer);
    update public.invoice_items i set style_number_snapshot=s.style_number from public.styles s where i.invoice_id=new.id and i.style_id=s.id;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_catalog_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op='DELETE' then raise exception 'Archive catalog records instead of deleting' using errcode='23514'; end if;
  if tg_table_name='document_templates' then
    if old.status='published' then raise exception 'Published templates are immutable' using errcode='23514'; end if;
  elsif tg_table_name='styles' then
    if new.style_number<>old.style_number and exists(select 1 from public.invoice_items i join public.invoices b on b.id=i.invoice_id
      where i.style_id=old.id and b.status<>'draft') then raise exception 'Issued style numbers are immutable' using errcode='23514'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare previous jsonb; current_row jsonb; item_count integer;
begin
  if tg_op='DELETE' then
    if old.status<>'draft' then raise exception 'Issued documents cannot be deleted' using errcode='23514'; end if;
    return old;
  end if;
  if tg_op='UPDATE' then
    if new.workspace_id<>old.workspace_id or new.entity_id<>old.entity_id then raise exception 'Document scope is immutable' using errcode='23514'; end if;
    if old.status<>'draft' then
      previous:=to_jsonb(old)-array['status','cancelled_at','cancelled_by','cancel_reason','updated_at','updated_by','version'];
      current_row:=to_jsonb(new)-array['status','cancelled_at','cancelled_by','cancel_reason','updated_at','updated_by','version'];
      if previous<>current_row or old.status='cancelled' or new.status<>'cancelled' then
        raise exception 'Issued document contents are immutable' using errcode='23514';
      end if;
    elsif new.status='cancelled' then raise exception 'Issue the draft before cancellation' using errcode='23514'; end if;
  end if;
  if new.status='issued' and (tg_op='INSERT' or old.status='draft') then
    if tg_table_name='invoices' then select count(*) into item_count from public.invoice_items where invoice_id=new.id;
    else select count(*) into item_count from public.dc_items where dc_id=new.id; end if;
    if item_count=0 then raise exception 'Add at least one item before issuing' using errcode='23514'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_entity_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if (new.numbering_mode,new.financial_year_start_month) is distinct from (old.numbering_mode,old.financial_year_start_month)
    and exists(select 1 from public.document_sequences where entity_id=old.id and next_number>1) then
    raise exception 'Numbering mode and financial year are fixed after first issuance. Use an administrator migration for a period transition.' using errcode='23514';
  end if;
  if new.default_invoice_template_id is not null and not exists(select 1 from public.document_templates where id=new.default_invoice_template_id and entity_id=new.id and document_type='invoice' and status='published') then
    raise exception 'Choose a published invoice template from this company' using errcode='23514';
  end if;
  if new.default_dc_template_id is not null and not exists(select 1 from public.document_templates where id=new.default_dc_template_id and entity_id=new.id and document_type='delivery_challan' and status='published') then
    raise exception 'Choose a published challan template from this company' using errcode='23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parent_status text; rowdata jsonb:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
begin
  if tg_op='UPDATE' and ((to_jsonb(new)->>'invoice_id') is distinct from (to_jsonb(old)->>'invoice_id')
    or (to_jsonb(new)->>'dc_id') is distinct from (to_jsonb(old)->>'dc_id')) then
    raise exception 'Item parent is immutable' using errcode='23514';
  end if;
  if tg_table_name='invoice_items' then
    select status into parent_status from public.invoices where id=(rowdata->>'invoice_id')::uuid for update;
  else select status into parent_status from public.delivery_challans where id=(rowdata->>'dc_id')::uuid for update; end if;
  if parent_status is distinct from 'draft' then raise exception 'Only draft items may be changed' using errcode='23514'; end if;
  return coalesce(new,old);
end $function$

CREATE OR REPLACE FUNCTION public.guard_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare inv public.invoices; paid numeric;
begin
  if tg_op='DELETE' then raise exception 'Receipts cannot be deleted' using errcode='23514'; end if;
  select * into strict inv from public.invoices where id=new.invoice_id for update;
  if tg_op='UPDATE' then
    if old.status<>'posted' or new.status<>'reversed' or
      to_jsonb(old)-array['status','reversed_at','reversed_by','reversal_reason'] <>
      to_jsonb(new)-array['status','reversed_at','reversed_by','reversal_reason'] then
      raise exception 'Reverse the original receipt to correct it' using errcode='23514';
    end if;
  else
    select coalesce(sum(amount),0) into paid from public.payments where invoice_id=inv.id and status='posted';
    if inv.status<>'issued' or new.currency<>inv.currency or new.payment_date<inv.invoice_date or new.amount>inv.grand_total-paid then
      raise exception 'Receipt exceeds balance or invoice is ineligible' using errcode='23514';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.initialize_workspace()
 RETURNS TABLE(id uuid, name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
  workspace_id_value uuid;
begin
  if actor is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise insufficient_privilege using message = 'A registered account is required';
  end if;

  insert into public.workspaces (owner_user_id) values (actor)
  on conflict (owner_user_id) do nothing;

  select w.id into strict workspace_id_value
    from public.workspaces w where w.owner_user_id = actor;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (workspace_id_value, actor, 'owner')
  on conflict (workspace_id, user_id) do nothing;

  return query select w.id, w.name from public.workspaces w where w.id = workspace_id_value;
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_challan(p_entity uuid, p_id uuid, p_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; d public.delivery_challans; num jsonb;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict d from public.delivery_challans where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  if d.status<>'draft' then return public.challan_payload(p_id); end if;
  if d.version<>p_version then raise exception 'Draft changed. Reload before issuing.' using errcode='40001'; end if;
  if d.related_invoice_id is not null then
    perform 1 from public.invoices where id=d.related_invoice_id and status='issued' for share;
    if not found then raise exception 'Related invoice was cancelled' using errcode='23514'; end if;
  end if;
  num:=public.allocate_document_number(p_entity,'delivery_challan',d.dc_date);
  update public.delivery_challans set status='issued',document_number=num->>'number',period_key=num->>'period',sequence_number=(num->>'sequence')::bigint,
    number_prefix_snapshot=num->>'prefix',numbering_mode_snapshot=num->>'mode',period_start_snapshot=(num->>'start')::date,
    period_end_snapshot=(num->>'end')::date,issued_at=clock_timestamp(),issued_by=auth.uid() where id=p_id;
  insert into public.document_files(workspace_id,entity_id,dc_id,template_id,variant) values(ws,p_entity,p_id,d.template_id,'original');
  return public.challan_payload(p_id);
end $function$

CREATE OR REPLACE FUNCTION public.issue_invoice(p_entity uuid, p_id uuid, p_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; inv public.invoices; number jsonb; buyer public.customers;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict inv from public.invoices where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  if inv.status<>'draft' then return public.invoice_payload(p_id); end if;
  if inv.version<>p_version then raise exception 'Draft changed. Reload before issuing.' using errcode='40001'; end if;
  select * into buyer from public.customers where id=inv.customer_id and is_active for share;
  if buyer.id is null then raise exception 'Customer is archived' using errcode='23514'; end if;
  perform 1 from public.styles s join public.invoice_items i on i.style_id=s.id where i.invoice_id=p_id order by s.id for share of s;
  if exists(select 1 from public.invoice_items i join public.styles s on s.id=i.style_id where i.invoice_id=p_id and not s.is_active) then
    raise exception 'A style on this draft is archived' using errcode='23514';
  end if;
  number:=public.allocate_document_number(p_entity,'invoice',inv.invoice_date);
  update public.invoices set status='issued',document_number=number->>'number',period_key=number->>'period',sequence_number=(number->>'sequence')::bigint,
    number_prefix_snapshot=number->>'prefix',numbering_mode_snapshot=number->>'mode',period_start_snapshot=(number->>'start')::date,
    period_end_snapshot=(number->>'end')::date,issued_at=clock_timestamp(),issued_by=auth.uid() where id=p_id;
  insert into public.document_files(workspace_id,entity_id,invoice_id,template_id,variant) values(ws,p_entity,p_id,inv.template_id,'original');
  return public.invoice_payload(p_id);
end $function$

CREATE OR REPLACE FUNCTION public.preview_invoice(p_entity uuid, p_bill jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  -- Exception subtransactions undo every catalog/draft/audit write while retaining local variables.
  begin
    result:=public.save_invoice_draft(p_entity,p_bill);
    raise exception using errcode='ZP001',message='Preview complete';
  exception when sqlstate 'ZP001' then null;
  end;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.publish_template(p_entity uuid, p_type text, p_settings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; template public.document_templates; next_version integer;
begin
  ws:=public.require_entity(p_entity,true);
  -- Serializes publishes without lock upgrades on the company row.
  perform pg_advisory_xact_lock(hashtextextended(p_entity::text||p_type,0));
  if p_type not in ('invoice','delivery_challan') or jsonb_typeof(p_settings)<>'object'
    or coalesce(p_settings->>'accent','') !~ '^#[0-9a-fA-F]{6}$' or coalesce(p_settings->>'preset','structured') not in ('structured','minimal') then
    raise exception 'Invalid template settings' using errcode='23514';
  end if;
  select coalesce(max(version_number),0)+1 into next_version from public.document_templates where entity_id=p_entity and document_type=p_type and name='Default';
  insert into public.document_templates(workspace_id,entity_id,document_type,name,version_number,status,settings_json,published_at,created_by,updated_by)
    values(ws,p_entity,p_type,'Default',next_version,'published',p_settings,clock_timestamp(),auth.uid(),auth.uid()) returning * into template;
  if p_type='invoice' then update public.billing_entities set default_invoice_template_id=template.id where id=p_entity;
  else update public.billing_entities set default_dc_template_id=template.id where id=p_entity; end if;
  return to_jsonb(template);
end $function$

CREATE OR REPLACE FUNCTION public.record_payment_internal(p_entity uuid, p_id uuid, p_receipt jsonb, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; previous public.idempotency_keys; inv public.invoices; result jsonb; fingerprint text:=md5(p_id::text||p_receipt::text);
begin
  ws:=public.require_entity(p_entity);
  insert into public.idempotency_keys(workspace_id,actor_user_id,operation,key,request_hash)
    values(ws,auth.uid(),'payment',p_key,fingerprint) on conflict do nothing;
  select * into strict previous from public.idempotency_keys where workspace_id=ws and actor_user_id=auth.uid() and operation='payment' and key=p_key for update;
  if previous.request_hash<>fingerprint then raise exception 'Request key reused with different payment' using errcode='23505'; end if;
  if previous.response_json is not null then return previous.response_json; end if;
  select * into strict inv from public.invoices where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  insert into public.payments(workspace_id,entity_id,invoice_id,payment_date,amount,method,reference_number,notes,posted_by)
    values(ws,p_entity,p_id,(p_receipt->>'date')::date,(p_receipt->>'cents')::numeric/100,p_receipt->>'method',p_receipt->>'reference',p_receipt->>'notes',auth.uid());
  result:=public.invoice_payload(p_id);
  update public.idempotency_keys set resource_id=p_id,response_json=result where workspace_id=ws and actor_user_id=auth.uid() and operation='payment' and key=p_key;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.report_data(p_entities uuid[], p_type text, p_from date, p_as_of date, p_recorded_through timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; zone text; boundary timestamptz; headers jsonb; rows jsonb;
begin
  select id,timezone into ws,zone from public.workspaces where owner_user_id=auth.uid();
  if ws is null or p_entities is null or cardinality(p_entities)=0 or exists(select 1 from unnest(p_entities) q(entity_id) where q.entity_id is null or not exists(
    select 1 from public.billing_entities e where e.id=q.entity_id and e.workspace_id=ws)) then raise exception 'Invalid report scope' using errcode='42501'; end if;
  if p_from>p_as_of then raise exception 'Invalid report period' using errcode='23514'; end if;
  boundary:=(p_as_of+1)::timestamp at time zone zone;
  if p_type='challans' then
    headers:='["Challan","Recipient","Date","Items"]';
    select coalesce(jsonb_agg(jsonb_build_array(d.document_number,d.recipient_name,d.dc_date,
      (select string_agg(i.particulars,', ' order by i.sort_order) from public.dc_items i where i.dc_id=d.id)) order by d.dc_date,d.id),'[]') into rows
    from public.delivery_challans d where d.workspace_id=ws and d.entity_id=any(p_entities) and d.dc_date between p_from and p_as_of
      and d.issued_at<=p_recorded_through and not(coalesce(d.cancelled_at<boundary and d.cancelled_at<=p_recorded_through,false));
  elsif p_type='cancelled' then
    headers:='["Bill","Customer","Cancelled on","Reason","Original amount"]';
    select coalesce(jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.cancelled_at,b.cancel_reason,b.grand_total) order by b.cancelled_at,b.id),'[]') into rows
    from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and b.cancelled_at<=p_recorded_through
      and (b.cancelled_at at time zone zone)::date between p_from and p_as_of;
  elsif p_type='collections' then
    headers:='["Bill","Date","Method","Amount"]';
    select coalesce(jsonb_agg(jsonb_build_array(b.document_number,p.payment_date,p.method,p.amount) order by p.payment_date,p.id),'[]') into rows
    from public.payments p join public.invoices b on b.id=p.invoice_id
    where p.workspace_id=ws and p.entity_id=any(p_entities) and p.payment_date between p_from and p_as_of
      and p.posted_at<=p_recorded_through and not(coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false));
  elsif p_type in ('billing','outstanding','customers','monthly','print-type','companies') then
    with eligible as (
      select b.*,
        coalesce((select sum(p.amount) from public.payments p where p.invoice_id=b.id and p.payment_date<=p_as_of and p.posted_at<=p_recorded_through
          and not(coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false))),0) paid
      from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and b.invoice_date<=p_as_of and b.issued_at<=p_recorded_through
        and not(coalesce(b.cancelled_at<boundary and b.cancelled_at<=p_recorded_through,false))
    ), grouped as (
      select case when p_type='customers' then b.entity_id::text||':'||b.customer_id::text when p_type='monthly' then to_char(b.invoice_date,'YYYY-MM')
        else b.entity_id::text end grouping_key,
        min(case when p_type='customers' then (b.seller_snapshot->>'legal_name')||' · '||(b.customer_snapshot->>'legal_name')
          when p_type='monthly' then to_char(b.invoice_date,'YYYY-MM') else b.seller_snapshot->>'legal_name' end) label,
        sum(b.grand_total) total
      from eligible b where b.invoice_date>=p_from group by 1
    ), print_groups as (
      select coalesce(i.print_type_snapshot,'Unspecified') label,sum(i.line_total) total
        from eligible b join public.invoice_items i on i.invoice_id=b.id where b.invoice_date>=p_from group by 1
      union all
      select 'Round off',sum(b.round_off) from eligible b where b.invoice_date>=p_from having sum(b.round_off)<>0
    )
    select case when p_type='billing' then coalesce((select jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.invoice_date,b.grand_total) order by b.invoice_date,b.id) from eligible b where b.invoice_date>=p_from),'[]')
      when p_type='outstanding' then coalesce((select jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.due_date,b.grand_total-b.paid) order by b.due_date,b.id) from eligible b where b.grand_total>b.paid),'[]')
      when p_type='print-type' then coalesce((select jsonb_agg(jsonb_build_array(label,total) order by label) from print_groups),'[]')
      else coalesce((select jsonb_agg(jsonb_build_array(label,total) order by label) from grouped),'[]') end into rows;
    headers:=case when p_type='billing' then '["Bill","Customer","Date","Amount"]'::jsonb
      when p_type='outstanding' then '["Bill","Customer","Due date","Outstanding"]'::jsonb
      else '["Group","Amount"]'::jsonb end;
  else raise exception 'Unknown report' using errcode='23514'; end if;
  return jsonb_build_object('headers',headers,'rows',rows,'from',p_from,'asOf',p_as_of,'recordedThrough',p_recorded_through,'timezone',zone,'definitionVersion','v1');
end $function$

CREATE OR REPLACE FUNCTION public.request_filtered_export(p_entities uuid[], p_type text, p_from date, p_as_of date, p_format text, p_customer uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare dataset jsonb; ws uuid; result public.report_exports; names jsonb;
begin
  dataset:=public.filtered_report_data(p_entities,p_type,p_from,p_as_of,clock_timestamp(),p_customer);
  select id into strict ws from public.workspaces where owner_user_id=auth.uid();
  select jsonb_agg(jsonb_build_object('id',id,'name',legal_name) order by legal_name) into names from public.billing_entities where id=any(p_entities) and workspace_id=ws;
  insert into public.report_exports(workspace_id,requested_by,report_type,entity_ids,filters_json,as_of_date,recorded_through,business_timezone,
    title_snapshot,entity_names_snapshot,format,data_snapshot,expires_at,report_definition_version)
    values(ws,auth.uid(),p_type,p_entities,jsonb_build_object('from',p_from,'asOf',p_as_of,'customerId',p_customer),p_as_of,(dataset->>'recordedThrough')::timestamptz,
      dataset->>'timezone',initcap(replace(p_type,'-',' '))||' report',names,p_format,dataset,clock_timestamp()+interval '7 days','v2') returning * into result;
  insert into public.audit_logs(workspace_id,actor_user_id,action,resource_type,resource_id,metadata_json)
    values(ws,auth.uid(),'export_requested','report_exports',result.id,jsonb_build_object('type',p_type,'entities',p_entities));
  return to_jsonb(result);
end $function$

