CREATE OR REPLACE FUNCTION public.touch_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op='UPDATE' then
    new.updated_at:=now(); new.version:=old.version+1; new.updated_by:=auth.uid();
    if new.workspace_id<>old.workspace_id then raise exception 'Workspace is immutable' using errcode='23514'; end if;
    if tg_table_name<>'billing_entities' and (to_jsonb(new)->>'entity_id') is distinct from (to_jsonb(old)->>'entity_id') then
      raise exception 'Company is immutable' using errcode='23514';
    end if;
  else new.created_by:=auth.uid(); new.updated_by:=auth.uid(); end if;
  if tg_table_name in ('billing_entities','customers','styles') then
    new.archived_at:=case when new.is_active then null else coalesce(new.archived_at,now()) end;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.update_catalog(p_entity uuid, p_table text, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; result jsonb;
begin
  ws:=public.require_entity(p_entity,true);
  if p_table='styles' then
    update public.styles set is_active=coalesce((p_data->>'is_active')::boolean,is_active),name=coalesce(p_data->>'name',name),description=coalesce(p_data->>'description',description)
      where id=p_id and workspace_id=ws and entity_id=p_entity returning to_jsonb(styles.*) into result;
  elsif p_table in ('print_types','placements','units') then
    if p_id is null then
      execute format('insert into public.%I(workspace_id,entity_id,code,label) values($1,$2,$3,$4) returning to_jsonb(%I.*)',p_table,p_table)
        into result using ws,p_entity,upper(btrim(p_data->>'code')),btrim(p_data->>'label');
