  created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id),updated_by uuid references auth.users(id),
  foreign key(workspace_id,entity_id) references public.billing_entities(workspace_id,id),
  unique(workspace_id,entity_id,id),
  check(cgst_rate+sgst_rate+igst_rate+other_tax_rate<=100),
  check((tax_mode='none' and cgst_rate+sgst_rate+igst_rate+other_tax_rate=0)
    or (tax_mode='intra_state' and igst_rate=0 and other_tax_rate=0)
    or (tax_mode='inter_state' and cgst_rate=0 and sgst_rate=0 and other_tax_rate=0)
    or (tax_mode='other' and cgst_rate=0 and sgst_rate=0 and igst_rate=0))
);

create table public.document_templates (
  id uuid primary key default gen_random_uuid(),workspace_id uuid not null,entity_id uuid not null,
  document_type text not null check(document_type in ('invoice','delivery_challan')),
  name text not null,version_number integer not null check(version_number>0),
  status text not null default 'draft' check(status in ('draft','published')),
  settings_schema_version integer not null default 1,
  settings_json jsonb not null default '{}' check(jsonb_typeof(settings_json)='object'),
  renderer_version text not null default 'thogai-v1',published_at timestamptz,
  created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id),updated_by uuid references auth.users(id),
  version bigint not null default 1,
  foreign key(workspace_id,entity_id) references public.billing_entities(workspace_id,id),
  unique(workspace_id,entity_id,id),unique(workspace_id,entity_id,document_type,name,version_number),
  check((status='published')=(published_at is not null))
);

create table public.styles (
  id uuid primary key default gen_random_uuid(),workspace_id uuid not null,entity_id uuid not null,
  style_number text not null check(length(btrim(style_number)) between 1 and 100 and style_number !~ '[[:cntrl:]]'),
  normalized_style_number text collate "C" generated always as (upper(btrim(style_number))) stored,
  name text,description text,default_print_type_id uuid,default_placement_id uuid,default_unit_id uuid,
  is_active boolean not null default true,archived_at timestamptz,
  created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
  version bigint not null default 1,created_by uuid references auth.users(id),updated_by uuid references auth.users(id),
  foreign key(workspace_id,entity_id) references public.billing_entities(workspace_id,id),
  foreign key(workspace_id,entity_id,default_print_type_id) references public.print_types(workspace_id,entity_id,id),
  foreign key(workspace_id,entity_id,default_placement_id) references public.placements(workspace_id,entity_id,id),
  foreign key(workspace_id,entity_id,default_unit_id) references public.units(workspace_id,entity_id,id),
  unique(workspace_id,entity_id,normalized_style_number),unique(workspace_id,entity_id,id)
);

create table public.audit_logs (
  id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),entity_id uuid,
  actor_user_id uuid references auth.users(id),actor_type text not null default 'user' check(actor_type in ('user','system')),
  action text not null,resource_type text not null,resource_id uuid not null,request_id text,
  before_json jsonb,after_json jsonb,metadata_json jsonb not null default '{}',occurred_at timestamptz not null default now(),
  foreign key(workspace_id,entity_id) references public.billing_entities(workspace_id,id)
);
create index audit_resource_idx on public.audit_logs(resource_type,resource_id,occurred_at);
create index audit_entity_idx on public.audit_logs(workspace_id,entity_id,occurred_at desc);

create function public.audit_record() returns trigger language plpgsql security definer set search_path='' as $$
declare rowdata jsonb := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
begin
  insert into public.audit_logs(workspace_id,entity_id,actor_user_id,action,resource_type,resource_id,before_json,after_json)
  values ((rowdata->>'workspace_id')::uuid,
    case when tg_table_name='billing_entities' then (rowdata->>'id')::uuid else (rowdata->>'entity_id')::uuid end,
    auth.uid(),lower(tg_op),tg_table_name,(rowdata->>'id')::uuid,
    case when tg_op<>'INSERT' then to_jsonb(old) end,case when tg_op<>'DELETE' then to_jsonb(new) end);
  return coalesce(new,old);
end $$;

create function public.touch_record() returns trigger language plpgsql set search_path='' as $$
begin
  if tg_op='UPDATE' then
    new.updated_at:=now(); new.version:=old.version+1; new.updated_by:=auth.uid();
    if new.workspace_id<>old.workspace_id then raise exception 'Workspace is immutable' using errcode='23514'; end if;
    if tg_table_name<>'billing_entities' and (to_jsonb(new)->>'entity_id') is distinct from (to_jsonb(old)->>'entity_id') then
      raise exception 'Company is immutable' using errcode='23514';
    end if;
  else new.created_by:=auth.uid(); new.updated_by:=auth.uid(); end if;
  if tg_table_name in ('billing_entities','customers','styles') then
    new.archived_at:=case when new.is_active then null else coalesce(new.archived_at,now()) end;
  end if;
  return new;
end $$;

create function public.seed_entity_catalog() returns trigger language plpgsql security definer set search_path='' as $$
declare template_id uuid;
begin
  insert into public.print_types(workspace_id,entity_id,code,label,sort_order)
    select new.workspace_id,new.id,v.code,v.label,v.n from (values
      ('DTF','DTF',1),('SUBLIMATION','Sublimation',2),('HEAT_TRANSFER','Heat Transfer',3),('PUFF','Puff',4),
      ('PLASTISOL','Plastisol',5),('HD','HD / High Density',6),('SCREEN_PRINTING','Screen Printing',7),('OTHER','Other',8)
    ) v(code,label,n) on conflict do nothing;
  insert into public.placements(workspace_id,entity_id,code,label,sort_order)
    select new.workspace_id,new.id,v.code,v.label,v.n from (values
      ('FRONT','Front',1),('BACK','Back',2),('LEFT_CHEST','Left Chest',3),('RIGHT_CHEST','Right Chest',4),
      ('SLEEVE','Sleeve',5),('NECK','Neck',6),('OTHER','Other',7)) v(code,label,n) on conflict do nothing;
  insert into public.units(workspace_id,entity_id,code,label,sort_order)
    select new.workspace_id,new.id,v.code,v.label,v.n from (values ('PCS','Pieces',1),('BUNDLE','Bundles',2),('BOX','Boxes',3)) v(code,label,n)
    on conflict do nothing;
  insert into public.document_templates(workspace_id,entity_id,document_type,name,version_number,status,published_at,settings_json)
    values(new.workspace_id,new.id,'invoice','Default',1,'published',now(),'{"preset":"structured","accent":"#7c3bd1"}')
    returning id into template_id;
  update public.billing_entities set default_invoice_template_id=template_id where id=new.id;
  insert into public.document_templates(workspace_id,entity_id,document_type,name,version_number,status,published_at,settings_json)
    values(new.workspace_id,new.id,'delivery_challan','Default',1,'published',now(),'{"preset":"minimal","accent":"#7c3bd1"}')
    returning id into template_id;
  update public.billing_entities set default_dc_template_id=template_id where id=new.id;
  return new;
end $$;

-- Seed pre-existing entities through the same trigger, without duplicating identities.
create trigger entity_catalog_seed after insert on public.billing_entities for each row execute function public.seed_entity_catalog();
do $$
declare e public.billing_entities;
begin
  for e in select * from public.billing_entities loop
    insert into public.print_types(workspace_id,entity_id,code,label,sort_order)
      select e.workspace_id,e.id,v.code,v.label,v.n from (values ('DTF','DTF',1),('SUBLIMATION','Sublimation',2),
      ('HEAT_TRANSFER','Heat Transfer',3),('PUFF','Puff',4),('PLASTISOL','Plastisol',5),('HD','HD / High Density',6),
      ('SCREEN_PRINTING','Screen Printing',7),('OTHER','Other',8)) v(code,label,n);
    insert into public.placements(workspace_id,entity_id,code,label)
      select e.workspace_id,e.id,upper(replace(label,' ','_')),label from unnest(array['Front','Back','Left Chest','Right Chest','Sleeve','Neck','Other']) label;
    insert into public.units(workspace_id,entity_id,code,label) values(e.workspace_id,e.id,'PCS','Pieces'),(e.workspace_id,e.id,'BUNDLE','Bundles'),(e.workspace_id,e.id,'BOX','Boxes');
    insert into public.document_templates(workspace_id,entity_id,document_type,name,version_number,status,published_at,settings_json)
      values(e.workspace_id,e.id,'invoice','Default',1,'published',now(),'{"preset":"structured","accent":"#7c3bd1"}'),
      (e.workspace_id,e.id,'delivery_challan','Default',1,'published',now(),'{"preset":"minimal","accent":"#7c3bd1"}');
    update public.billing_entities b set default_invoice_template_id=(select id from public.document_templates t where t.entity_id=e.id and t.document_type='invoice'),
      default_dc_template_id=(select id from public.document_templates t where t.entity_id=e.id and t.document_type='delivery_challan') where b.id=e.id;
  end loop;
end $$;

alter table public.billing_entities
  add foreign key(workspace_id,id,default_tax_profile_id) references public.tax_profiles(workspace_id,entity_id,id),
  add foreign key(workspace_id,id,default_invoice_template_id) references public.document_templates(workspace_id,entity_id,id),
  add foreign key(workspace_id,id,default_dc_template_id) references public.document_templates(workspace_id,entity_id,id);

create function public.resolve_style(p_entity uuid,p_number text) returns public.styles
language plpgsql security definer set search_path='' as $$
declare workspace uuid; result public.styles;
begin
  workspace:=public.require_entity(p_entity,true);
  if p_number is null or length(btrim(p_number)) not between 1 and 100 or p_number ~ '[[:cntrl:]]' then
    raise exception 'Enter a style number of 1 to 100 characters' using errcode='23514';
  end if;
  insert into public.styles(workspace_id,entity_id,style_number,created_by,updated_by)
    values(workspace,p_entity,btrim(p_number),auth.uid(),auth.uid())
    on conflict(workspace_id,entity_id,normalized_style_number) do nothing;
  select * into strict result from public.styles where workspace_id=workspace and entity_id=p_entity
    and normalized_style_number=upper(btrim(p_number)) collate "C" for share;
  if not result.is_active then raise exception 'This style is archived. Restore it before use.' using errcode='23514'; end if;
  return result;
end $$;

-- Customer historical reads must survive company archival.
drop policy customers_entity_owner on public.customers;
create policy customers_read on public.customers for select to authenticated using (
  entity_id is not null and workspace_id in(select id from public.workspaces where owner_user_id=auth.uid()));
create policy customers_write on public.customers for all to authenticated
using(exists(select 1 from public.billing_entities e where e.id=entity_id and e.workspace_id=customers.workspace_id and e.is_active))
with check(exists(select 1 from public.billing_entities e where e.id=entity_id and e.workspace_id=customers.workspace_id and e.is_active));

do $$
declare tab text;
begin
  foreach tab in array array['styles','print_types','placements','units','tax_profiles','document_templates','audit_logs'] loop
    execute format('alter table public.%I enable row level security',tab);
    execute format('revoke all on public.%I from public,anon,authenticated',tab);
    execute format('grant select on public.%I to authenticated',tab);
    execute format('create policy owner_read on public.%I for select to authenticated using(workspace_id in(select id from public.workspaces where owner_user_id=(select auth.uid())))',tab);
  end loop;
  foreach tab in array array['billing_entities','customers','styles','print_types','placements','units','tax_profiles'] loop
    execute format('create trigger metadata before insert or update on public.%I for each row execute function public.touch_record()',tab);
    execute format('create trigger audit after insert or update or delete on public.%I for each row execute function public.audit_record()',tab);
  end loop;
end $$;

grant insert(dc_prefix,numbering_mode,default_terms,rounding_increment),update(dc_prefix,numbering_mode,default_terms,rounding_increment) on public.billing_entities to authenticated;
revoke all on function public.require_entity(uuid,boolean),public.audit_record(),public.touch_record(),public.seed_entity_catalog() from public,anon,authenticated;
revoke all on function public.resolve_style(uuid,text) from public,anon;
grant execute on function public.resolve_style(uuid,text) to authenticated;

create function public.invoice_payload(p_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'id',b.id,'version',b.version,'seller',b.seller_snapshot||coalesce(b.payment_details_snapshot,'{}'),'customer',b.customer_snapshot,
    'date',b.invoice_date,'due',b.due_date,'reference',coalesce(b.reference_number,''),'notes',coalesce(b.notes,''),
    'terms',b.terms,'status',initcap(b.status),'number',b.document_number,'currency',b.currency,
    'discountCents',b.invoice_discount_total*100,'taxBasisPoints',coalesce((select max(other_tax_rate)*100 from public.invoice_items where invoice_id=b.id),0),
    'totalCents',b.grand_total*100,'subtotalCents',b.subtotal*100,'taxCents',b.tax_total*100,
    'taxableCents',b.taxable_total*100,'roundOffCents',b.round_off*100,
    'accent',b.template_snapshot->'settings_json'->>'accent',
    'cancellation',case when b.status='cancelled' then jsonb_build_object('date',(b.cancelled_at at time zone w.timezone)::date,'reason',b.cancel_reason) end,
    'lines',coalesce((select jsonb_agg(jsonb_build_object('id',i.sort_order,'databaseId',i.id,'description',i.particulars,
      'quantity',i.quantity::text,'rate',rtrim(rtrim(i.unit_rate::text,'0'),'.'),'style',i.style_number_snapshot,'styleId',i.style_id,
      'printType',i.print_type_snapshot,'placement',i.placement_snapshot,'unit',i.unit_snapshot,
      'amountCents',i.line_total*100,'taxableCents',i.taxable_amount*100,'taxCents',i.tax_amount*100)
      order by i.sort_order) from public.invoice_items i where i.invoice_id=b.id),'[]'),
    'receipts',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'date',p.payment_date,'cents',p.amount*100,
      'method',p.method,'reference',coalesce(p.reference_number,''),'status',p.status,'reversedAt',p.reversed_at,
      'reversalReason',p.reversal_reason) order by p.posted_at) from public.payments p where p.invoice_id=b.id),'[]')
  ) from public.invoices b join public.workspaces w on w.id=b.workspace_id where b.id=p_id and w.owner_user_id=auth.uid()
$$;

create function public.save_invoice_draft(p_entity uuid,p_bill jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  ws uuid; bid uuid:=(p_bill->>'id')::uuid; inv public.invoices; seller public.billing_entities; buyer public.customers;
  item jsonb; ordinal integer; style public.styles; unit_row public.units; pt public.print_types; place public.placements;
  tax public.tax_profiles; qty numeric; rate numeric; gross numeric; discount numeric; adjustment numeric;
  header_discount numeric:=coalesce((p_bill->>'discountCents')::numeric,0)/100;
  template public.document_templates; base numeric; shared_tax numeric;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict seller from public.billing_entities where id=p_entity;
  select * into buyer from public.customers where id=(p_bill->>'customerId')::uuid
    and workspace_id=ws and entity_id=p_entity and is_active for share;
  if buyer.id is null then raise exception 'Choose an active customer from this company' using errcode='23514'; end if;
  if bid is null then bid:=gen_random_uuid(); end if;
  insert into public.invoices(id,workspace_id,entity_id,customer_id,invoice_date,due_date)
    values(bid,ws,p_entity,buyer.id,(p_bill->>'date')::date,(p_bill->>'due')::date) on conflict(id) do nothing;
  select * into strict inv from public.invoices where id=bid and workspace_id=ws and entity_id=p_entity for update;
  if inv.status<>'draft' then raise exception 'Only drafts can be edited' using errcode='23514'; end if;
  if p_bill ? 'version' and inv.version<>(p_bill->>'version')::bigint then
    raise exception 'This draft changed. Reload before saving.' using errcode='40001';
  end if;
  if jsonb_typeof(p_bill->'lines')<>'array' or jsonb_array_length(p_bill->'lines') not between 1 and 100 then
    raise exception 'Add between 1 and 100 items' using errcode='23514';
  end if;
  select * into template from public.document_templates where id=seller.default_invoice_template_id
    and entity_id=p_entity and document_type='invoice' and status='published';
  if template.id is null then raise exception 'Publish an invoice template first' using errcode='23514'; end if;
  delete from public.invoice_items where invoice_id=bid;
  -- Resolve in normalized style order so multiple-line saves use a stable lock order.
  for item,ordinal in select value, ordinality::integer from jsonb_array_elements(p_bill->'lines') with ordinality
    order by upper(btrim(coalesce(value->>'style',''))),ordinality loop
    style:=null; pt:=null; place:=null; tax:=null;
    if nullif(btrim(item->>'style'),'') is not null then style:=public.resolve_style(p_entity,item->>'style'); end if;
    select * into unit_row from public.units where entity_id=p_entity and is_active
      and code=coalesce(nullif(item->>'unitCode',''),'PCS') for share;
    if unit_row.id is null then raise exception 'Unknown or archived unit' using errcode='23514'; end if;
    if nullif(item->>'printType','') is not null then
      select * into pt from public.print_types where entity_id=p_entity and is_active and label=item->>'printType' for share;
      if pt.id is null then raise exception 'Unknown or archived print type' using errcode='23514'; end if;
    end if;
    if nullif(item->>'placement','') is not null then
      select * into place from public.placements where entity_id=p_entity and is_active and label=item->>'placement' for share;
      if place.id is null then raise exception 'Unknown or archived placement' using errcode='23514'; end if;
    end if;
    qty:=(item->>'quantity')::numeric; rate:=(item->>'rate')::numeric;
    if qty<>round(qty,3) or rate<>round(rate,4) then raise exception 'Quantity or rate precision exceeded' using errcode='23514'; end if;
    gross:=round(qty*rate,2); discount:=coalesce((item->>'discountCents')::numeric,0)/100;
    adjustment:=coalesce((item->>'adjustmentCents')::numeric,0)/100;
    if item ? 'taxProfileId' or seller.default_tax_profile_id is not null then
      select * into tax from public.tax_profiles where id=coalesce((item->>'taxProfileId')::uuid,seller.default_tax_profile_id)
        and entity_id=p_entity and is_active for share;
      if tax.id is null then raise exception 'Unknown or archived tax profile' using errcode='23514'; end if;
    end if;
    shared_tax:=case when p_bill ? 'taxBasisPoints' then (p_bill->>'taxBasisPoints')::numeric/100 else coalesce(tax.other_tax_rate,0) end;
    insert into public.invoice_items(workspace_id,entity_id,invoice_id,sort_order,style_id,style_number_snapshot,
      print_type_id,placement_id,unit_id,print_type_snapshot,placement_snapshot,unit_snapshot,placement_detail,
      particulars,quantity,unit_rate,gross_amount,line_discount_amount,line_adjustment_amount,line_adjustment_reason,
      taxable_amount,line_total,tax_profile_id,tax_mode_snapshot,cgst_rate,sgst_rate,igst_rate,other_tax_rate)
    values(ws,p_entity,bid,ordinal,style.id,style.style_number,pt.id,place.id,unit_row.id,pt.label,place.label,unit_row.label,item->>'placementDetail',
      btrim(item->>'description'),qty,rate,gross,discount,adjustment,item->>'adjustmentReason',gross+adjustment-discount,gross+adjustment-discount,
      tax.id,case when p_bill ? 'taxBasisPoints' then case when shared_tax>0 then 'other' else 'none' end else coalesce(tax.tax_mode,'none') end,
      0,0,0,0);
    -- Rates and rounded components are set together to preserve item checks.
    update public.invoice_items set
      cgst_rate=case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.cgst_rate,0) end,
      sgst_rate=case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.sgst_rate,0) end,
      igst_rate=case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.igst_rate,0) end,
      other_tax_rate=shared_tax,
      cgst_amount=round(taxable_amount*case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.cgst_rate,0) end/100,2),
      sgst_amount=round(taxable_amount*case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.sgst_rate,0) end/100,2),
      igst_amount=round(taxable_amount*case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.igst_rate,0) end/100,2),
      other_tax_amount=round(taxable_amount*shared_tax/100,2),
      tax_amount=round(taxable_amount*case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.cgst_rate,0) end/100,2)
        +round(taxable_amount*case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.sgst_rate,0) end/100,2)
        +round(taxable_amount*case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.igst_rate,0) end/100,2)+round(taxable_amount*shared_tax/100,2),
      line_total=taxable_amount+round(taxable_amount*case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.cgst_rate,0) end/100,2)
        +round(taxable_amount*case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.sgst_rate,0) end/100,2)
        +round(taxable_amount*case when p_bill ? 'taxBasisPoints' then 0 else coalesce(tax.igst_rate,0) end/100,2)+round(taxable_amount*shared_tax/100,2)
      where invoice_id=bid and sort_order=ordinal;
  end loop;
  select sum(taxable_amount) into base from public.invoice_items where invoice_id=bid;
  if header_discount<0 or header_discount>base or header_discount<>round(header_discount,2) then
    raise exception 'Discount exceeds subtotal' using errcode='23514';
  end if;
  if header_discount>0 then
    with shares as (
      select id,sort_order,header_discount*100*taxable_amount/base raw from public.invoice_items where invoice_id=bid
    ), ranked as (
      select *,row_number() over(order by raw-floor(raw) desc,sort_order) rank,
        header_discount*100-sum(floor(raw)) over() remainder from shares
    ), amounts as (
      select id,(floor(raw)+case when rank<=remainder then 1 else 0 end)/100 share from ranked
    ), recalculated as (
      select i.id,a.share,i.taxable_amount-a.share taxable from public.invoice_items i join amounts a on a.id=i.id
    )
    update public.invoice_items i set invoice_discount_share=r.share,taxable_amount=r.taxable,
      cgst_amount=round(r.taxable*cgst_rate/100,2),sgst_amount=round(r.taxable*sgst_rate/100,2),
      igst_amount=round(r.taxable*igst_rate/100,2),other_tax_amount=round(r.taxable*other_tax_rate/100,2),
      tax_amount=round(r.taxable*cgst_rate/100,2)+round(r.taxable*sgst_rate/100,2)+round(r.taxable*igst_rate/100,2)+round(r.taxable*other_tax_rate/100,2),
      line_total=r.taxable+round(r.taxable*cgst_rate/100,2)+round(r.taxable*sgst_rate/100,2)+round(r.taxable*igst_rate/100,2)+round(r.taxable*other_tax_rate/100,2)
    from recalculated r where i.id=r.id;
  end if;
  update public.invoices b set customer_id=buyer.id,invoice_date=(p_bill->>'date')::date,due_date=(p_bill->>'due')::date,
    reference_number=p_bill->>'reference',notes=p_bill->>'notes',terms=coalesce(p_bill->>'terms',seller.default_terms),
    seller_snapshot=to_jsonb(seller),customer_snapshot=to_jsonb(buyer),
    payment_details_snapshot=jsonb_build_object('bank_details',coalesce(p_bill->'bank',seller.bank_details),'upi_id',coalesce(p_bill->>'upi',seller.upi_id)),
    template_id=template.id,template_snapshot=to_jsonb(template),renderer_version=template.renderer_version,
    rounding_increment_snapshot=seller.rounding_increment,
    subtotal=s.gross,line_adjustment_total=s.adjustment,line_discount_total=s.discounts,invoice_discount_total=header_discount,
    taxable_total=s.taxable,cgst_total=s.cgst,sgst_total=s.sgst,igst_total=s.igst,other_tax_total=s.other,tax_total=s.tax,
    round_off=case when seller.rounding_increment>0 then round((s.taxable+s.tax)/seller.rounding_increment)*seller.rounding_increment-(s.taxable+s.tax) else 0 end,
    grand_total=case when seller.rounding_increment>0 then round((s.taxable+s.tax)/seller.rounding_increment)*seller.rounding_increment else s.taxable+s.tax end
    from (select sum(gross_amount) gross,sum(line_adjustment_amount) adjustment,sum(line_discount_amount) discounts,
      sum(taxable_amount) taxable,sum(cgst_amount) cgst,sum(sgst_amount) sgst,sum(igst_amount) igst,sum(other_tax_amount) other,sum(tax_amount) tax
      from public.invoice_items where invoice_id=bid) s where b.id=bid;
  return public.invoice_payload(bid);
end $$;

create function public.allocate_document_number(p_entity uuid,p_type text,p_date date)
returns jsonb language plpgsql security definer set search_path='' as $$
declare e public.billing_entities; ws uuid; start_year integer; starts date; ends date; period text; prefix text; serial bigint;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict e from public.billing_entities where id=p_entity;
  if p_type not in ('invoice','delivery_challan') then raise exception 'Invalid document type'; end if;
  prefix:=case when p_type='invoice' then coalesce(nullif(btrim(e.invoice_prefix),''),e.entity_code)
    else coalesce(nullif(btrim(e.dc_prefix),''),e.entity_code||'/DC') end;
  if e.numbering_mode='continuous' then period:='CONTINUOUS';
  else
    start_year:=extract(year from p_date)::integer-case when extract(month from p_date)<e.financial_year_start_month then 1 else 0 end;
    starts:=make_date(start_year,e.financial_year_start_month,1);ends:=(starts+interval '1 year'-interval '1 day')::date;
    period:=right(start_year::text,2)||'-'||right((start_year+1)::text,2);
  end if;
  insert into public.document_sequences(workspace_id,entity_id,document_type,period_key,period_start,period_end)
    values(ws,p_entity,p_type,period,starts,ends) on conflict do nothing;
  update public.document_sequences set next_number=next_number+1,updated_at=now()
    where workspace_id=ws and entity_id=p_entity and document_type=p_type and period_key=period returning next_number-1 into serial;
  return jsonb_build_object('number',prefix||'/'||case when period='CONTINUOUS' then '' else period||'/' end||lpad(serial::text,greatest(4,length(serial::text)),'0'),
    'period',period,'sequence',serial,'prefix',prefix,'mode',e.numbering_mode,'start',starts,'end',ends);
end $$;

create function public.issue_invoice(p_entity uuid,p_id uuid,p_version bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; inv public.invoices; number jsonb; buyer public.customers;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict inv from public.invoices where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  if inv.status<>'draft' then return public.invoice_payload(p_id); end if;
  if inv.version<>p_version then raise exception 'Draft changed. Reload before issuing.' using errcode='40001'; end if;
  select * into buyer from public.customers where id=inv.customer_id and is_active for share;
  if buyer.id is null then raise exception 'Customer is archived' using errcode='23514'; end if;
  perform 1 from public.styles s join public.invoice_items i on i.style_id=s.id where i.invoice_id=p_id order by s.id for share of s;
  if exists(select 1 from public.invoice_items i join public.styles s on s.id=i.style_id where i.invoice_id=p_id and not s.is_active) then
    raise exception 'A style on this draft is archived' using errcode='23514';
  end if;
  number:=public.allocate_document_number(p_entity,'invoice',inv.invoice_date);
  update public.invoices set status='issued',document_number=number->>'number',period_key=number->>'period',sequence_number=(number->>'sequence')::bigint,
    number_prefix_snapshot=number->>'prefix',numbering_mode_snapshot=number->>'mode',period_start_snapshot=(number->>'start')::date,
    period_end_snapshot=(number->>'end')::date,issued_at=clock_timestamp(),issued_by=auth.uid() where id=p_id;
  insert into public.document_files(workspace_id,entity_id,invoice_id,template_id,variant) values(ws,p_entity,p_id,inv.template_id,'original');
  return public.invoice_payload(p_id);
end $$;

create function public.cancel_invoice(p_entity uuid,p_id uuid,p_reason text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; inv public.invoices;
begin
  ws:=public.require_entity(p_entity);
  select * into strict inv from public.invoices where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  if inv.status='cancelled' then return public.invoice_payload(p_id); end if;
  if inv.status<>'issued' or coalesce(length(btrim(p_reason)),0)=0 then raise exception 'An issued invoice and cancellation reason are required' using errcode='23514'; end if;
  if exists(select 1 from public.payments where invoice_id=p_id and status='posted') then raise exception 'Reverse receipts before cancelling' using errcode='23514'; end if;
  update public.invoices set status='cancelled',cancelled_at=clock_timestamp(),cancelled_by=auth.uid(),cancel_reason=btrim(p_reason) where id=p_id;
  insert into public.document_files(workspace_id,entity_id,invoice_id,template_id,variant) values(ws,p_entity,p_id,inv.template_id,'cancelled');
  return public.invoice_payload(p_id);
end $$;

create function public.record_payment(p_entity uuid,p_id uuid,p_receipt jsonb,p_key text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; previous public.idempotency_keys; inv public.invoices; result jsonb; fingerprint text:=md5(p_id::text||p_receipt::text);
begin
  ws:=public.require_entity(p_entity);
  insert into public.idempotency_keys(workspace_id,actor_user_id,operation,key,request_hash)
    values(ws,auth.uid(),'payment',p_key,fingerprint) on conflict do nothing;
  select * into strict previous from public.idempotency_keys where workspace_id=ws and actor_user_id=auth.uid() and operation='payment' and key=p_key for update;
  if previous.request_hash<>fingerprint then raise exception 'Request key reused with different payment' using errcode='23505'; end if;
  if previous.response_json is not null then return previous.response_json; end if;
  select * into strict inv from public.invoices where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  insert into public.payments(workspace_id,entity_id,invoice_id,payment_date,amount,method,reference_number,notes,posted_by)
    values(ws,p_entity,p_id,(p_receipt->>'date')::date,(p_receipt->>'cents')::numeric/100,p_receipt->>'method',p_receipt->>'reference',p_receipt->>'notes',auth.uid());
  result:=public.invoice_payload(p_id);
  update public.idempotency_keys set resource_id=p_id,response_json=result where workspace_id=ws and actor_user_id=auth.uid() and operation='payment' and key=p_key;
  return result;
end $$;

create function public.reverse_payment(p_entity uuid,p_id uuid,p_payment uuid,p_reason text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid;
begin
  ws:=public.require_entity(p_entity);
  perform 1 from public.invoices where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  if not found then raise exception 'Invoice not found' using errcode='42501'; end if;
  if coalesce(length(btrim(p_reason)),0)=0 then raise exception 'Enter a reversal reason' using errcode='23514'; end if;
  update public.payments set status='reversed',reversed_at=clock_timestamp(),reversed_by=auth.uid(),reversal_reason=btrim(p_reason)
    where id=p_payment and invoice_id=p_id and status='posted';
  if not found and not exists(select 1 from public.payments where id=p_payment and invoice_id=p_id) then raise exception 'Receipt not found' using errcode='42501'; end if;
  return public.invoice_payload(p_id);
end $$;

create function public.delete_invoice_draft(p_entity uuid,p_id uuid,p_version bigint) returns void
language plpgsql security definer set search_path='' as $$
declare ws uuid; inv public.invoices;
begin
  ws:=public.require_entity(p_entity);
  select * into strict inv from public.invoices where id=p_id and entity_id=p_entity and workspace_id=ws for update;
  if inv.status<>'draft' or inv.version<>p_version then raise exception 'Draft changed or already issued' using errcode='23514'; end if;
  delete from public.invoice_items where invoice_id=p_id;
  delete from public.invoices where id=p_id;
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
    and p.proname in ('invoice_payload','save_invoice_draft','allocate_document_number','issue_invoice','cancel_invoice','record_payment','reverse_payment','delete_invoice_draft') loop
    execute format('revoke all on function %s from public,anon,authenticated',f.signature);
    if f.signature::text not like '%allocate_document_number%' then execute format('grant execute on function %s to authenticated',f.signature); end if;
  end loop;
end $$;

create function public.challan_payload(p_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',d.id,'version',d.version,'entityId',d.entity_id,'number',d.document_number,'date',d.dc_date,
   'status',initcap(d.status),'recipient',d.recipient_name,'customerId',d.customer_id,
   'from',d.from_address->>'text','to',d.to_address->>'text','notes',coalesce(d.notes,''),'billId',d.related_invoice_id,
   'billNumber',(select document_number from public.invoices where id=d.related_invoice_id),
   'seller',d.sender_snapshot,'template',d.template_snapshot,'cancellation',case when d.status='cancelled' then jsonb_build_object('reason',d.cancel_reason,'date',d.cancelled_at) end,
   'acknowledgement',(select to_jsonb(a) from public.delivery_acknowledgements a where a.dc_id=d.id),
   'items',coalesce((select jsonb_agg(jsonb_build_object('description',i.particulars,'quantity',i.quantity::text,'unit',i.unit_snapshot,'remarks',i.remarks)
     order by i.sort_order) from public.dc_items i where i.dc_id=d.id),'[]'))
 from public.delivery_challans d join public.workspaces w on w.id=d.workspace_id where d.id=p_id and w.owner_user_id=auth.uid()
$$;

create function public.save_challan_draft(p_entity uuid,p_challan jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare ws uuid; did uuid:=coalesce((p_challan->>'id')::uuid,gen_random_uuid()); d public.delivery_challans;
  seller public.billing_entities; template public.document_templates; linked public.invoices; item jsonb; n integer; unit_row public.units; customer uuid;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict seller from public.billing_entities where id=p_entity;
  customer:=nullif(p_challan->>'customerId','')::uuid;
  if nullif(p_challan->>'billId','') is not null then
    select * into linked from public.invoices where id=(p_challan->>'billId')::uuid and entity_id=p_entity and workspace_id=ws and status='issued' for share;
    if linked.id is null then raise exception 'Choose an issued invoice from this company' using errcode='23514'; end if;
    customer:=linked.customer_id;
  end if;
  if customer is not null then
    perform 1 from public.customers where id=customer and workspace_id=ws and entity_id=p_entity and is_active for share;
    if not found then raise exception 'Customer is archived or belongs to another company' using errcode='23514'; end if;
  end if;
  select * into strict template from public.document_templates where id=seller.default_dc_template_id and entity_id=p_entity and document_type='delivery_challan' and status='published';
  if jsonb_array_length(p_challan->'items') not between 1 and 100 then raise exception 'Add between 1 and 100 items' using errcode='23514'; end if;
  insert into public.delivery_challans(id,workspace_id,entity_id,recipient_name,dc_date,from_address,to_address)
    values(did,ws,p_entity,btrim(p_challan->>'recipient'),(p_challan->>'date')::date,jsonb_build_object('text',p_challan->>'from'),jsonb_build_object('text',p_challan->>'to'))
    on conflict(id) do nothing;
  select * into strict d from public.delivery_challans where id=did and workspace_id=ws and entity_id=p_entity for update;
  if d.status<>'draft' or (p_challan ? 'version' and d.version<>(p_challan->>'version')::bigint) then raise exception 'Draft changed or already issued' using errcode='40001'; end if;
  delete from public.dc_items where dc_id=did;
  for item,n in select value,ordinality::integer from jsonb_array_elements(p_challan->'items') with ordinality loop
    select * into unit_row from public.units where entity_id=p_entity and is_active and label=item->>'unit' for share;
    if unit_row.id is null then raise exception 'Choose an active delivery unit' using errcode='23514'; end if;
    insert into public.dc_items(workspace_id,entity_id,dc_id,sort_order,particulars,quantity,unit_id,unit_snapshot,remarks)
      values(ws,p_entity,did,n,btrim(item->>'description'),(item->>'quantity')::numeric,unit_row.id,unit_row.label,item->>'remarks');
  end loop;
  if coalesce(length(btrim(p_challan->>'from')),0)=0 or coalesce(length(btrim(p_challan->>'to')),0)=0 then raise exception 'Enter both delivery addresses' using errcode='23514'; end if;
  update public.delivery_challans set customer_id=customer,recipient_name=btrim(p_challan->>'recipient'),dc_date=(p_challan->>'date')::date,
    related_invoice_id=linked.id,from_address=jsonb_build_object('text',p_challan->>'from'),to_address=jsonb_build_object('text',p_challan->>'to'),
    sender_snapshot=to_jsonb(seller),recipient_snapshot=jsonb_build_object('name',p_challan->>'recipient','address',p_challan->>'to'),
    template_id=template.id,template_snapshot=to_jsonb(template),renderer_version=template.renderer_version,notes=p_challan->>'notes' where id=did;
  return public.challan_payload(did);
end $$;

create function public.issue_challan(p_entity uuid,p_id uuid,p_version bigint) returns jsonb language plpgsql security definer set search_path='' as $$
declare ws uuid; d public.delivery_challans; num jsonb;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict d from public.delivery_challans where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  if d.status<>'draft' then return public.challan_payload(p_id); end if;
  if d.version<>p_version then raise exception 'Draft changed. Reload before issuing.' using errcode='40001'; end if;
  if d.related_invoice_id is not null then
    perform 1 from public.invoices where id=d.related_invoice_id and status='issued' for share;
    if not found then raise exception 'Related invoice was cancelled' using errcode='23514'; end if;
  end if;
  num:=public.allocate_document_number(p_entity,'delivery_challan',d.dc_date);
  update public.delivery_challans set status='issued',document_number=num->>'number',period_key=num->>'period',sequence_number=(num->>'sequence')::bigint,
    number_prefix_snapshot=num->>'prefix',numbering_mode_snapshot=num->>'mode',period_start_snapshot=(num->>'start')::date,
    period_end_snapshot=(num->>'end')::date,issued_at=clock_timestamp(),issued_by=auth.uid() where id=p_id;
  insert into public.document_files(workspace_id,entity_id,dc_id,template_id,variant) values(ws,p_entity,p_id,d.template_id,'original');
  return public.challan_payload(p_id);
end $$;

create function public.cancel_challan(p_entity uuid,p_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path='' as $$
declare ws uuid; d public.delivery_challans;
begin
  ws:=public.require_entity(p_entity);
  select * into strict d from public.delivery_challans where id=p_id and entity_id=p_entity and workspace_id=ws for update;
  if d.status='cancelled' then return public.challan_payload(p_id); end if;
  if d.status<>'issued' or coalesce(length(btrim(p_reason)),0)=0 then raise exception 'Enter a reason for cancelling an issued challan' using errcode='23514'; end if;
  update public.delivery_challans set status='cancelled',cancelled_at=clock_timestamp(),cancelled_by=auth.uid(),cancel_reason=btrim(p_reason) where id=p_id;
  insert into public.document_files(workspace_id,entity_id,dc_id,template_id,variant) values(ws,p_entity,p_id,d.template_id,'cancelled');
  return public.challan_payload(p_id);
end $$;

create function public.acknowledge_delivery(p_entity uuid,p_id uuid,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare ws uuid; result jsonb;
begin
  ws:=public.require_entity(p_entity);
  perform 1 from public.delivery_challans where id=p_id and workspace_id=ws and entity_id=p_entity and status='issued' for update;
  if not found then raise exception 'An issued challan is required' using errcode='23514'; end if;
  insert into public.delivery_acknowledgements(workspace_id,entity_id,dc_id,received_by,received_at,notes,recorded_by)
    values(ws,p_entity,p_id,p_data->>'receivedBy',(p_data->>'receivedAt')::timestamptz,p_data->>'notes',auth.uid())
    on conflict(dc_id) do nothing;
  return public.challan_payload(p_id);
end $$;

create function public.publish_template(p_entity uuid,p_type text,p_settings jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare ws uuid; template public.document_templates; next_version integer;
begin
  ws:=public.require_entity(p_entity,true);
  -- Serializes publishes without lock upgrades on the company row.
  perform pg_advisory_xact_lock(hashtextextended(p_entity::text||p_type,0));
  if p_type not in ('invoice','delivery_challan') or jsonb_typeof(p_settings)<>'object'
    or coalesce(p_settings->>'accent','') !~ '^#[0-9a-fA-F]{6}$' or coalesce(p_settings->>'preset','structured') not in ('structured','minimal') then
    raise exception 'Invalid template settings' using errcode='23514';
  end if;
  select coalesce(max(version_number),0)+1 into next_version from public.document_templates where entity_id=p_entity and document_type=p_type and name='Default';
  insert into public.document_templates(workspace_id,entity_id,document_type,name,version_number,status,settings_json,published_at,created_by,updated_by)
    values(ws,p_entity,p_type,'Default',next_version,'published',p_settings,clock_timestamp(),auth.uid(),auth.uid()) returning * into template;
  if p_type='invoice' then update public.billing_entities set default_invoice_template_id=template.id where id=p_entity;
  else update public.billing_entities set default_dc_template_id=template.id where id=p_entity; end if;
  return to_jsonb(template);
end $$;

create function public.update_catalog(p_entity uuid,p_table text,p_id uuid,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare ws uuid; result jsonb;
begin
  ws:=public.require_entity(p_entity,true);
  if p_table='styles' then
    update public.styles set is_active=coalesce((p_data->>'is_active')::boolean,is_active),name=coalesce(p_data->>'name',name),description=coalesce(p_data->>'description',description)
      where id=p_id and workspace_id=ws and entity_id=p_entity returning to_jsonb(styles.*) into result;
  elsif p_table in ('print_types','placements','units') then
    if p_id is null then
      execute format('insert into public.%I(workspace_id,entity_id,code,label) values($1,$2,$3,$4) returning to_jsonb(%I.*)',p_table,p_table)
        into result using ws,p_entity,upper(btrim(p_data->>'code')),btrim(p_data->>'label');
    else
      execute format('update public.%I set label=coalesce($1,label),is_active=coalesce($2,is_active) where id=$3 and workspace_id=$4 and entity_id=$5 returning to_jsonb(%I.*)',p_table,p_table)
        into result using p_data->>'label',(p_data->>'is_active')::boolean,p_id,ws,p_entity;
    end if;
  else raise exception 'Invalid catalog' using errcode='23514'; end if;
  if result is null then raise exception 'Record not found' using errcode='42501'; end if;
  return result;
end $$;

create function public.save_preferences(p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare ws uuid; result jsonb;
begin
  select id into strict ws from public.workspaces where owner_user_id=auth.uid();
  insert into public.user_preferences(workspace_id,user_id,last_entity_id,skip_entity_selector,preferences_json)
    values(ws,auth.uid(),(p_data->>'lastEntityId')::uuid,coalesce((p_data->>'skipEntitySelector')::boolean,false),coalesce(p_data->'preferences','{}'))
    on conflict(workspace_id,user_id) do update set last_entity_id=excluded.last_entity_id,skip_entity_selector=excluded.skip_entity_selector,
      preferences_json=excluded.preferences_json,updated_at=now() returning to_jsonb(user_preferences.*) into result;
  return result;
end $$;

create function public.claim_document_file(p_entity uuid,p_type text,p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare ws uuid; file public.document_files; variant_value text; state text;
begin
  ws:=public.require_entity(p_entity);
  if p_type='invoice' then select status into state from public.invoices where id=p_id and entity_id=p_entity and workspace_id=ws for share;
  elsif p_type='delivery_challan' then select status into state from public.delivery_challans where id=p_id and entity_id=p_entity and workspace_id=ws for share;
  else raise exception 'Invalid document type' using errcode='23514'; end if;
  if state is null or state='draft' then raise exception 'Issue the document before generating a PDF' using errcode='23514'; end if;
  variant_value:=case when state='cancelled' then 'cancelled' else 'original' end;
  select * into strict file from public.document_files where entity_id=p_entity and variant=variant_value
    and (case when p_type='invoice' then invoice_id=p_id else dc_id=p_id end) for update;
  if file.status='ready' then return to_jsonb(file); end if;
  if file.status='processing' and file.lease_expires_at>clock_timestamp() then raise exception 'PDF generation is already running. Retry shortly.' using errcode='55P03'; end if;
  update public.document_files set status='processing',attempt_count=attempt_count+1,claim_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '2 minutes',updated_at=now()
    where id=file.id returning * into file;
  return to_jsonb(file);
end $$;

create function public.finish_document_file(p_entity uuid,p_id uuid,p_token uuid,p_result jsonb) returns void language plpgsql security definer set search_path='' as $$
declare ws uuid;
begin
  ws:=public.require_entity(p_entity);
  if p_result->>'path' is not null and p_result->>'path' not like ws::text||'/'||p_entity::text||'/%' then raise exception 'Invalid storage path' using errcode='42501'; end if;
  update public.document_files set status=case when p_result ? 'error' then 'failed' else 'ready' end,
    object_path=p_result->>'path',sha256=p_result->>'sha256',byte_size=(p_result->>'size')::bigint,
    last_error=p_result->>'error',generated_at=case when not(p_result ? 'error') then clock_timestamp() end,
    lease_expires_at=null,updated_at=now() where id=p_id and workspace_id=ws and entity_id=p_entity and claim_token=p_token and status='processing';
  if not found then raise exception 'PDF claim expired' using errcode='40001'; end if;
end $$;

insert into storage.buckets(id,name,public) values('report-exports','report-exports',false) on conflict do nothing;

-- Upload paths are workspace/entity/...; existing immutable objects cannot be overwritten.
create policy billing_private_read on storage.objects for select to authenticated using (
  bucket_id in ('billing-assets','invoice-pdfs','report-exports') and exists(
    select 1 from public.billing_entities e join public.workspaces w on w.id=e.workspace_id where w.owner_user_id=auth.uid()
      and split_part(name,'/',1)=w.id::text and split_part(name,'/',2)=e.id::text));
create policy billing_private_insert on storage.objects for insert to authenticated with check (
  bucket_id in ('billing-assets','invoice-pdfs','report-exports') and exists(
    select 1 from public.billing_entities e join public.workspaces w on w.id=e.workspace_id where w.owner_user_id=auth.uid()
      and split_part(name,'/',1)=w.id::text and split_part(name,'/',2)=e.id::text));

do $$
declare f record;
begin
  for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
    and p.proname in ('challan_payload','save_challan_draft','issue_challan','cancel_challan','acknowledge_delivery','publish_template','update_catalog','save_preferences','claim_document_file','finish_document_file') loop
