-- Materialize the report result at request time so retries reproduce the same export.
alter table public.report_exports add column data_snapshot jsonb not null default '{}';

create function public.report_data(p_entities uuid[],p_type text,p_from date,p_as_of date,p_recorded_through timestamptz default now())
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ws uuid; zone text; boundary timestamptz; headers jsonb; rows jsonb;
begin
  select id,timezone into ws,zone from public.workspaces where owner_user_id=auth.uid();
  if ws is null or p_entities is null or cardinality(p_entities)=0 or exists(select 1 from unnest(p_entities) q(entity_id) where q.entity_id is null or not exists(
    select 1 from public.billing_entities e where e.id=q.entity_id and e.workspace_id=ws)) then raise exception 'Invalid report scope' using errcode='42501'; end if;
  if p_from>p_as_of then raise exception 'Invalid report period' using errcode='23514'; end if;
  boundary:=(p_as_of+1)::timestamp at time zone zone;
  if p_type='challans' then
    headers:='["Challan","Recipient","Date","Items"]';
    select coalesce(jsonb_agg(jsonb_build_array(d.document_number,d.recipient_name,d.dc_date,
      (select string_agg(i.particulars,', ' order by i.sort_order) from public.dc_items i where i.dc_id=d.id)) order by d.dc_date,d.id),'[]') into rows
    from public.delivery_challans d where d.workspace_id=ws and d.entity_id=any(p_entities) and d.dc_date between p_from and p_as_of
      and d.issued_at<=p_recorded_through and not(coalesce(d.cancelled_at<boundary and d.cancelled_at<=p_recorded_through,false));
  elsif p_type='cancelled' then
    headers:='["Bill","Customer","Cancelled on","Reason","Original amount"]';
    select coalesce(jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.cancelled_at,b.cancel_reason,b.grand_total) order by b.cancelled_at,b.id),'[]') into rows
    from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and b.cancelled_at<=p_recorded_through
      and (b.cancelled_at at time zone zone)::date between p_from and p_as_of;
  elsif p_type='collections' then
    headers:='["Bill","Date","Method","Amount"]';
    select coalesce(jsonb_agg(jsonb_build_array(b.document_number,p.payment_date,p.method,p.amount) order by p.payment_date,p.id),'[]') into rows
    from public.payments p join public.invoices b on b.id=p.invoice_id
    where p.workspace_id=ws and p.entity_id=any(p_entities) and p.payment_date between p_from and p_as_of
      and p.posted_at<=p_recorded_through and not(coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false));
  elsif p_type in ('billing','outstanding','customers','monthly','print-type','companies') then
    with eligible as (
      select b.*,
        coalesce((select sum(p.amount) from public.payments p where p.invoice_id=b.id and p.payment_date<=p_as_of and p.posted_at<=p_recorded_through
          and not(coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false))),0) paid
      from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and b.invoice_date<=p_as_of and b.issued_at<=p_recorded_through
        and not(coalesce(b.cancelled_at<boundary and b.cancelled_at<=p_recorded_through,false))
    ), grouped as (
      select case when p_type='customers' then b.entity_id::text||':'||b.customer_id::text when p_type='monthly' then to_char(b.invoice_date,'YYYY-MM')
        else b.entity_id::text end grouping_key,
        min(case when p_type='customers' then (b.seller_snapshot->>'legal_name')||' · '||(b.customer_snapshot->>'legal_name')
          when p_type='monthly' then to_char(b.invoice_date,'YYYY-MM') else b.seller_snapshot->>'legal_name' end) label,
        sum(b.grand_total) total
      from eligible b where b.invoice_date>=p_from group by 1
    ), print_groups as (
      select coalesce(i.print_type_snapshot,'Unspecified') label,sum(i.line_total) total
        from eligible b join public.invoice_items i on i.invoice_id=b.id where b.invoice_date>=p_from group by 1
      union all
      select 'Round off',sum(b.round_off) from eligible b where b.invoice_date>=p_from having sum(b.round_off)<>0
    )
    select case when p_type='billing' then coalesce((select jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.invoice_date,b.grand_total) order by b.invoice_date,b.id) from eligible b where b.invoice_date>=p_from),'[]')
      when p_type='outstanding' then coalesce((select jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.due_date,b.grand_total-b.paid) order by b.due_date,b.id) from eligible b where b.grand_total>b.paid),'[]')
      when p_type='print-type' then coalesce((select jsonb_agg(jsonb_build_array(label,total) order by label) from print_groups),'[]')
      else coalesce((select jsonb_agg(jsonb_build_array(label,total) order by label) from grouped),'[]') end into rows;
    headers:=case when p_type='billing' then '["Bill","Customer","Date","Amount"]'::jsonb
      when p_type='outstanding' then '["Bill","Customer","Due date","Outstanding"]'::jsonb
      else '["Group","Amount"]'::jsonb end;
  else raise exception 'Unknown report' using errcode='23514'; end if;
  return jsonb_build_object('headers',headers,'rows',rows,'from',p_from,'asOf',p_as_of,'recordedThrough',p_recorded_through,'timezone',zone,'definitionVersion','v1');
end $$;

create function public.request_report_export(p_entities uuid[],p_type text,p_from date,p_as_of date,p_format text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare dataset jsonb; ws uuid; result public.report_exports; names jsonb;
begin
  dataset:=public.report_data(p_entities,p_type,p_from,p_as_of,clock_timestamp());
  select id into strict ws from public.workspaces where owner_user_id=auth.uid();
  select jsonb_agg(jsonb_build_object('id',id,'name',legal_name) order by legal_name) into names from public.billing_entities where id=any(p_entities) and workspace_id=ws;
  insert into public.report_exports(workspace_id,requested_by,report_type,entity_ids,filters_json,as_of_date,recorded_through,business_timezone,
    title_snapshot,entity_names_snapshot,format,data_snapshot,expires_at)
    values(ws,auth.uid(),p_type,p_entities,jsonb_build_object('from',p_from,'asOf',p_as_of),p_as_of,(dataset->>'recordedThrough')::timestamptz,
      dataset->>'timezone',initcap(replace(p_type,'-',' '))||' report',names,p_format,dataset,clock_timestamp()+interval '7 days') returning * into result;
  insert into public.audit_logs(workspace_id,actor_user_id,action,resource_type,resource_id,metadata_json)
    values(ws,auth.uid(),'export_requested','report_exports',result.id,jsonb_build_object('type',p_type,'entities',p_entities));
  return to_jsonb(result);
end $$;

create function public.claim_report_export(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare result public.report_exports;
begin
  select r.* into strict result from public.report_exports r join public.workspaces w on w.id=r.workspace_id where r.id=p_id and w.owner_user_id=auth.uid() for update of r;
  if result.expires_at<clock_timestamp() then raise exception 'Export expired. Request a new report.' using errcode='23514'; end if;
  if result.status='ready' then return to_jsonb(result); end if;
  if result.status='processing' and result.lease_expires_at>clock_timestamp() then raise exception 'Export is being generated' using errcode='55P03'; end if;
  update public.report_exports set status='processing',attempt_count=attempt_count+1,claim_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '2 minutes'
    where id=p_id returning * into result;
  return to_jsonb(result);
end $$;

create function public.finish_report_export(p_id uuid,p_token uuid,p_result jsonb) returns void language plpgsql security definer set search_path='' as $$
declare ws uuid; first_entity uuid;
begin
  select r.workspace_id,r.entity_ids[1] into ws,first_entity from public.report_exports r join public.workspaces w on w.id=r.workspace_id where r.id=p_id and w.owner_user_id=auth.uid();
  if ws is null or (p_result ? 'path' and p_result->>'path' not like ws::text||'/'||first_entity::text||'/%') then raise exception 'Invalid export' using errcode='42501'; end if;
  update public.report_exports set status=case when p_result ? 'error' then 'failed' else 'ready' end,
    object_path=p_result->>'path',sha256=p_result->>'sha256',byte_size=(p_result->>'size')::bigint,
    last_error=p_result->>'error',generated_at=case when not(p_result ? 'error') then clock_timestamp() end,lease_expires_at=null,updated_at=now()
    where id=p_id and status='processing' and claim_token=p_token;
  if not found then raise exception 'Export claim expired' using errcode='40001'; end if;
end $$;

revoke all on function public.report_data(uuid[],text,date,date,timestamptz),public.request_report_export(uuid[],text,date,date,text),public.claim_report_export(uuid),public.finish_report_export(uuid,uuid,jsonb) from public,anon;
grant execute on function public.report_data(uuid[],text,date,date,timestamptz),public.request_report_export(uuid[],text,date,date,text),public.claim_report_export(uuid),public.finish_report_export(uuid,uuid,jsonb) to authenticated;

-- Keep the original calculation engine private and require versions on subsequent edits.
alter function public.save_invoice_draft(uuid,jsonb) rename to save_invoice_draft_internal;
revoke all on function public.save_invoice_draft_internal(uuid,jsonb) from public,anon,authenticated;

create function public.save_invoice_draft(p_entity uuid,p_bill jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; inv public.invoices; prior public.idempotency_keys; result jsonb;
  input_id uuid:=(p_bill->>'id')::uuid; fingerprint text:=md5(p_bill::text);
begin
  ws:=public.require_entity(p_entity,true);
  if input_id is null then raise exception 'A draft ID is required' using errcode='23514'; end if;
  select * into inv from public.invoices where id=input_id and workspace_id=ws and entity_id=p_entity for update;
  if inv.id is not null and not(p_bill ? 'version') then
    select * into prior from public.idempotency_keys where workspace_id=ws and actor_user_id=auth.uid()
      and operation='draft_create' and key=input_id::text;
    if prior.request_hash=fingerprint then return public.invoice_payload(input_id); end if;
    raise exception 'Provide the current draft version before editing' using errcode='40001';
  end if;
  result:=public.save_invoice_draft_internal(p_entity,p_bill);
  if nullif(p_bill->>'replacementForInvoiceId','') is not null then
    perform 1 from public.invoices where id=(p_bill->>'replacementForInvoiceId')::uuid and workspace_id=ws and entity_id=p_entity
      and customer_id=(p_bill->>'customerId')::uuid and status='cancelled' for share;
    if not found then raise exception 'Replacement must reference a cancelled invoice for this customer' using errcode='23514'; end if;
    update public.invoices set replacement_for_invoice_id=(p_bill->>'replacementForInvoiceId')::uuid where id=input_id;
  end if;
  result:=public.invoice_payload(input_id);
  if inv.id is null then
    insert into public.idempotency_keys(workspace_id,actor_user_id,operation,key,request_hash,resource_id,response_json)
      values(ws,auth.uid(),'draft_create',input_id::text,fingerprint,input_id,result);
  end if;
  return result;
end $$;

alter function public.save_challan_draft(uuid,jsonb) rename to save_challan_draft_internal;
revoke all on function public.save_challan_draft_internal(uuid,jsonb) from public,anon,authenticated;
create function public.save_challan_draft(p_entity uuid,p_challan jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; d public.delivery_challans; prior public.idempotency_keys; result jsonb;
  input_id uuid:=(p_challan->>'id')::uuid;fingerprint text:=md5(p_challan::text);
begin
  ws:=public.require_entity(p_entity,true);
  if input_id is null then raise exception 'A challan ID is required' using errcode='23514'; end if;
  select * into d from public.delivery_challans where id=input_id and workspace_id=ws and entity_id=p_entity for update;
  if d.id is not null and not(p_challan ? 'version') then
    select * into prior from public.idempotency_keys where workspace_id=ws and actor_user_id=auth.uid()
      and operation='challan_create' and key=input_id::text;
    if prior.request_hash=fingerprint then return public.challan_payload(input_id); end if;
    raise exception 'Provide the current challan version before editing' using errcode='40001';
  end if;
  result:=public.save_challan_draft_internal(p_entity,p_challan);
  if d.id is null then
    insert into public.idempotency_keys(workspace_id,actor_user_id,operation,key,request_hash,resource_id,response_json)
      values(ws,auth.uid(),'challan_create',input_id::text,fingerprint,input_id,result);
  end if;
  return result;
end $$;

-- Include event times for historical dashboard balances, while retaining the UI payload contract.
create or replace function public.invoice_payload(p_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'id',b.id,'version',b.version,'seller',b.seller_snapshot||coalesce(b.payment_details_snapshot,'{}'),'customer',b.customer_snapshot,
    'date',b.invoice_date,'due',b.due_date,'reference',coalesce(b.reference_number,''),'notes',coalesce(b.notes,''),
    'terms',b.terms,'status',initcap(b.status),'number',b.document_number,'currency',b.currency,
    'issuedAt',b.issued_at,'cancelledAt',b.cancelled_at,'replacementForInvoiceId',b.replacement_for_invoice_id,
    'discountCents',b.invoice_discount_total*100,'taxBasisPoints',coalesce((select max(other_tax_rate)*100 from public.invoice_items where invoice_id=b.id),0),
    'totalCents',b.grand_total*100,'subtotalCents',b.subtotal*100,'taxCents',b.tax_total*100,
    'taxableCents',b.taxable_total*100,'roundOffCents',b.round_off*100,
    'accent',b.template_snapshot->'settings_json'->>'accent','templatePreset',b.template_snapshot->'settings_json'->>'preset',
    'cancellation',case when b.status='cancelled' then jsonb_build_object('date',(b.cancelled_at at time zone w.timezone)::date,'reason',b.cancel_reason) end,
    'lines',coalesce((select jsonb_agg(jsonb_build_object('id',i.sort_order,'databaseId',i.id,'description',i.particulars,
      'quantity',i.quantity::text,'rate',rtrim(rtrim(i.unit_rate::text,'0'),'.'),'style',i.style_number_snapshot,'styleId',i.style_id,
      'printType',i.print_type_snapshot,'placement',i.placement_snapshot,'unit',i.unit_snapshot,
      'amountCents',i.line_total*100,'taxableCents',i.taxable_amount*100,'taxCents',i.tax_amount*100)
      order by i.sort_order) from public.invoice_items i where i.invoice_id=b.id),'[]'),
    'receipts',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'date',p.payment_date,'cents',p.amount*100,
      'method',p.method,'reference',coalesce(p.reference_number,''),'status',p.status,'postedAt',p.posted_at,'reversedAt',p.reversed_at,
      'reversalReason',p.reversal_reason) order by p.posted_at) from public.payments p where p.invoice_id=b.id),'[]')
  ) from public.invoices b join public.workspaces w on w.id=b.workspace_id where b.id=p_id and w.owner_user_id=auth.uid()
$$;

alter table public.invoices
  add constraint safe_client_amounts check(subtotal<=90071992547409.91 and grand_total<=90071992547409.91),
  add constraint complete_issue_metadata check(status='draft' or (sequence_number is not null and numbering_mode_snapshot is not null
    and ((numbering_mode_snapshot='continuous' and period_start_snapshot is null and period_end_snapshot is null)
      or (numbering_mode_snapshot='financial_year' and period_start_snapshot is not null and period_end_snapshot>=period_start_snapshot)))),
  add constraint complete_cancel_metadata check(status<>'cancelled' or (cancelled_at is not null and cancel_reason is not null));
alter table public.delivery_challans
  add constraint complete_dc_issue_metadata check(status='draft' or (sequence_number is not null and period_key is not null and renderer_version is not null)),
  add constraint complete_dc_cancel_metadata check(status<>'cancelled' or (cancelled_at is not null and cancel_reason is not null));
alter table public.payments
  add constraint complete_reversal_metadata check(status<>'reversed' or (reversed_at is not null and reversal_reason is not null));

revoke all on function public.save_invoice_draft(uuid,jsonb),public.save_challan_draft(uuid,jsonb) from public,anon;
grant execute on function public.save_invoice_draft(uuid,jsonb),public.save_challan_draft(uuid,jsonb) to authenticated;

create function public.set_entity_asset(p_entity uuid,p_kind text,p_path text) returns void
language plpgsql security definer set search_path='' as $$
declare ws uuid;
begin
  ws:=public.require_entity(p_entity,true);
  if p_kind not in ('logo','signature') or left(p_path,length(ws::text||'/'||p_entity::text||'/'))<>ws::text||'/'||p_entity::text||'/'
    or not exists(select 1 from storage.objects where bucket_id='billing-assets' and name=p_path) then
    raise exception 'Invalid company asset' using errcode='23514';
  end if;
  if p_kind='logo' then update public.billing_entities set logo_path=p_path where id=p_entity;
  else update public.billing_entities set signature_path=p_path where id=p_entity; end if;
end $$;
revoke all on function public.set_entity_asset(uuid,text,text) from public,anon;
grant execute on function public.set_entity_asset(uuid,text,text) to authenticated;

-- Read services authorize workspace/entity selections independently of RLS.
create function public.authorize_report_entities(p_entities uuid[]) returns uuid
language plpgsql stable security definer set search_path='' as $$
declare ws uuid;
begin
  select id into ws from public.workspaces where owner_user_id=auth.uid();
  if ws is null or p_entities is null or cardinality(p_entities)=0 or cardinality(p_entities)>100
    or cardinality(p_entities)<>(select count(distinct x) from unnest(p_entities) x)
    or exists(select 1 from unnest(p_entities) q(id) where q.id is null or not exists(
      select 1 from public.billing_entities e where e.id=q.id and e.workspace_id=ws)) then
    raise exception 'Company selection is unavailable' using errcode='42501';
  end if;
  return ws;
end $$;

create function public.list_documents(p_entity uuid,p_kind text,p_filters jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare ws uuid; result jsonb; total bigint; n integer:=coalesce((p_filters->>'page')::integer,1);
  size integer:=coalesce((p_filters->>'pageSize')::integer,25); search text:=coalesce(p_filters->>'search','');
  as_of date:=coalesce((p_filters->>'asOf')::date,current_date); cutoff timestamptz:=now();
begin
  ws:=public.authorize_report_entities(array[p_entity]);
  if n<1 or n>100000 or size not between 1 and 100 or p_kind not in ('invoices','challans') then
    raise exception 'Invalid document filters' using errcode='23514';
  end if;
  if p_kind='invoices' then
    with candidates as (
      select b.id,b.invoice_date,b.created_at,b.grand_total,b.status,b.due_date,
        b.grand_total-coalesce((select sum(p.amount) from public.payments p where p.invoice_id=b.id and p.status='posted'),0) balance
      from public.invoices b where b.workspace_id=ws and b.entity_id=p_entity
        and (not(p_filters ? 'status') or b.status=p_filters->>'status')
        and (not(p_filters ? 'customerId') or b.customer_id=(p_filters->>'customerId')::uuid)
        and (not(p_filters ? 'from') or b.invoice_date>=(p_filters->>'from')::date)
        and (not(p_filters ? 'to') or b.invoice_date<=(p_filters->>'to')::date)
        and (not(p_filters ? 'minAmount') or b.grand_total>=(p_filters->>'minAmount')::numeric)
        and (not(p_filters ? 'maxAmount') or b.grand_total<=(p_filters->>'maxAmount')::numeric)
        and (search='' or strpos(lower(coalesce(b.document_number,'')||' '||coalesce(b.reference_number,'')||' '||coalesce(b.customer_snapshot->>'legal_name','')),lower(search))>0)
    ), filtered as (
      select * from candidates c where
        (not(p_filters ? 'paymentStatus') or exists(select 1 from public.invoices b where b.id=c.id and b.status='issued') and
          case when c.balance=0 then 'paid' when c.balance=c.grand_total then 'unpaid' else 'partially_paid' end=p_filters->>'paymentStatus')
        and (not(p_filters ? 'overdue') or (c.status='issued' and c.due_date<as_of and c.balance>0)=(p_filters->>'overdue')::boolean)
    ), paged as (
      select * from filtered order by
        case when p_filters->>'sort'='oldest' then invoice_date end asc,
        case when p_filters->>'sort'='amount_desc' then grand_total end desc,
        invoice_date desc,created_at desc,id limit size offset (n-1)*size
    )
    select (select count(*) from filtered),coalesce((select jsonb_agg(public.invoice_payload(id)||jsonb_build_object('outstanding',balance)
      order by case when p_filters->>'sort'='oldest' then invoice_date end asc,
      case when p_filters->>'sort'='amount_desc' then grand_total end desc,invoice_date desc,created_at desc,id) from paged),'[]') into total,result;
  else
    with filtered as (
      select d.* from public.delivery_challans d where d.workspace_id=ws and d.entity_id=p_entity
        and (not(p_filters ? 'status') or d.status=p_filters->>'status')
        and (not(p_filters ? 'customerId') or d.customer_id=(p_filters->>'customerId')::uuid)
        and (not(p_filters ? 'invoiceId') or d.related_invoice_id=(p_filters->>'invoiceId')::uuid)
        and (not(p_filters ? 'from') or d.dc_date>=(p_filters->>'from')::date)
        and (not(p_filters ? 'to') or d.dc_date<=(p_filters->>'to')::date)
        and (search='' or strpos(lower(coalesce(d.document_number,'')||' '||d.recipient_name),lower(search))>0)
    ), paged as (
      select * from filtered order by case when p_filters->>'sort'='oldest' then dc_date end asc,dc_date desc,created_at desc,id limit size offset (n-1)*size
    ) select (select count(*) from filtered),coalesce((select jsonb_agg(public.challan_payload(id) order by
      case when p_filters->>'sort'='oldest' then dc_date end asc,dc_date desc,created_at desc,id) from paged),'[]') into total,result;
  end if;
  return jsonb_build_object('data',result,'page',n,'pageSize',size,'total',total,'asOf',as_of,'recordedThrough',cutoff);
end $$;

create function public.dashboard_data(p_entities uuid[],p_from date,p_as_of date,p_recorded timestamptz default now(),p_customer uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ws uuid; zone text; boundary timestamptz; result jsonb;
begin
  ws:=public.authorize_report_entities(p_entities);
  select timezone into zone from public.workspaces where id=ws;
  if p_from is null or p_as_of is null or p_from>p_as_of or p_as_of-p_from>3660 or p_recorded is null or p_recorded>clock_timestamp() then
    raise exception 'Use a report period up to ten years and a valid recorded cutoff' using errcode='23514';
  end if;
  if p_customer is not null and not exists(select 1 from public.customers where id=p_customer and workspace_id=ws and entity_id=any(p_entities)) then
    raise exception 'Customer not found' using errcode='42501';
  end if;
  boundary:=(p_as_of+1)::timestamp at time zone zone;
  with eligible as (
    select b.*,coalesce((select sum(p.amount) from public.payments p where p.invoice_id=b.id and p.payment_date<=p_as_of and p.posted_at<=p_recorded
      and not coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded,false)),0) paid
    from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and (p_customer is null or b.customer_id=p_customer)
      and b.invoice_date<=p_as_of and b.issued_at<=p_recorded
      and not coalesce(b.cancelled_at<boundary and b.cancelled_at<=p_recorded,false)
  ), period_bills as (select * from eligible where invoice_date>=p_from), receipts as (
    select p.* from public.payments p join public.invoices b on b.id=p.invoice_id
    where p.workspace_id=ws and p.entity_id=any(p_entities) and (p_customer is null or b.customer_id=p_customer)
      and p.payment_date between p_from and p_as_of and p.posted_at<=p_recorded
      and not coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded,false)
  ), customer_totals as (
    select e.entity_id,e.customer_id,max(e.customer_snapshot->>'legal_name') name,
      coalesce(sum(e.grand_total) filter(where e.invoice_date>=p_from),0) billed,
      sum(e.grand_total-e.paid) outstanding,count(*) filter(where e.invoice_date>=p_from) invoice_count,
      max(e.invoice_date) last_invoice_date from eligible e group by e.entity_id,e.customer_id
  ), month_series as (
    select generate_series(date_trunc('month',p_from::timestamp),date_trunc('month',p_as_of::timestamp),interval '1 month')::date as month_start
  ), printing as (
    select coalesce(i.print_type_snapshot,'Unspecified') label,sum(i.line_total) amount
      from period_bills b join public.invoice_items i on i.invoice_id=b.id group by 1
    union all select 'Round off',sum(round_off) from period_bills having sum(round_off)<>0
  ), quantities as (
    select coalesce(i.print_type_snapshot,'Unspecified') print_type,i.unit_snapshot unit,sum(i.quantity) quantity
      from period_bills b join public.invoice_items i on i.invoice_id=b.id group by 1,2
  ), totals as (
    select coalesce(sum(grand_total),0) billed,count(*) invoice_count from period_bills
  ) select jsonb_build_object(
    'currency','INR','from',p_from,'asOf',p_as_of,'recordedThrough',p_recorded,'timezone',zone,
    'billed',(select billed from totals),'invoiceCount',(select invoice_count from totals),
    'averageInvoiceValue',(select case when invoice_count=0 then 0 else round(billed/invoice_count,2) end from totals),
    'collected',(select coalesce(sum(amount),0) from receipts),
    'outstanding',(select coalesce(sum(grand_total-paid),0) from eligible),
    'overdue',(select coalesce(sum(grand_total-paid),0) from eligible where due_date<p_as_of),
    'cancelled',(select jsonb_build_object('count',count(*),'amount',coalesce(sum(grand_total),0)) from public.invoices
      where workspace_id=ws and entity_id=any(p_entities) and (p_customer is null or customer_id=p_customer)
        and cancelled_at<=p_recorded and (cancelled_at at time zone zone)::date between p_from and p_as_of),
    'challanCount',(select count(*) from public.delivery_challans where workspace_id=ws and entity_id=any(p_entities)
      and (p_customer is null or customer_id=p_customer) and dc_date between p_from and p_as_of and issued_at<=p_recorded
      and not coalesce(cancelled_at<boundary and cancelled_at<=p_recorded,false)),
    'entities',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.legal_name,
      'billed',(select coalesce(sum(grand_total),0) from period_bills where entity_id=c.id),
      'collected',(select coalesce(sum(amount),0) from receipts where entity_id=c.id),
      'outstanding',(select coalesce(sum(grand_total-paid),0) from eligible where entity_id=c.id),
      'invoiceCount',(select count(*) from period_bills where entity_id=c.id)) order by c.legal_name,c.id),'[]')
      from public.billing_entities c where c.id=any(p_entities)),
    'monthly',(select coalesce(jsonb_agg(jsonb_build_object('month',to_char(m.month_start,'YYYY-MM'),
      'billed',(select coalesce(sum(grand_total),0) from period_bills where date_trunc('month',invoice_date::timestamp)::date=m.month_start),
      'collected',(select coalesce(sum(amount),0) from receipts where date_trunc('month',payment_date::timestamp)::date=m.month_start)) order by m.month_start),'[]') from month_series m),
    'entityMonthly',(select coalesce(jsonb_agg(jsonb_build_object('entityId',e.id,'month',to_char(m.month_start,'YYYY-MM'),
      'billed',(select coalesce(sum(grand_total),0) from period_bills where entity_id=e.id and date_trunc('month',invoice_date::timestamp)::date=m.month_start),
      'collected',(select coalesce(sum(amount),0) from receipts where entity_id=e.id and date_trunc('month',payment_date::timestamp)::date=m.month_start)) order by e.id,m.month_start),'[]')
      from month_series m cross join public.billing_entities e where e.id=any(p_entities)),
    'aging',(select jsonb_build_object(
      'notDue',coalesce(sum(grand_total-paid) filter(where due_date>=p_as_of),0),
      'days1to30',coalesce(sum(grand_total-paid) filter(where p_as_of-due_date between 1 and 30),0),
      'days31to60',coalesce(sum(grand_total-paid) filter(where p_as_of-due_date between 31 and 60),0),
      'days61to90',coalesce(sum(grand_total-paid) filter(where p_as_of-due_date between 61 and 90),0),
      'days91plus',coalesce(sum(grand_total-paid) filter(where p_as_of-due_date>90),0)) from eligible),
    'paymentStatuses',(select jsonb_build_object('paid',count(*) filter(where grand_total=paid),
      'partiallyPaid',count(*) filter(where paid>0 and paid<grand_total),'unpaid',count(*) filter(where paid=0 and grand_total>0)) from eligible),
    'topCustomers',(select coalesce(jsonb_agg(to_jsonb(c) order by billed desc,entity_id,customer_id),'[]') from
      (select * from customer_totals order by billed desc,entity_id,customer_id limit 10) c),
    'printTypes',(select coalesce(jsonb_agg(to_jsonb(p) order by label),'[]') from printing p),
    'quantities',(select coalesce(jsonb_agg(to_jsonb(q) order by print_type,unit),'[]') from quantities q),
    'recentInvoices',(select coalesce(jsonb_agg(public.invoice_payload(b.id) order by invoice_date desc,id),'[]') from
      (select id,invoice_date from period_bills order by invoice_date desc,id limit 5) b)
  ) into result;
  return result;
end $$;

create function public.customer_summary(p_entity uuid,p_customer uuid,p_from date,p_as_of date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare ws uuid; customer jsonb;
begin
  ws:=public.authorize_report_entities(array[p_entity]);
  select to_jsonb(c) into customer from public.customers c where id=p_customer and workspace_id=ws and entity_id=p_entity;
  if customer is null then raise exception 'Customer not found' using errcode='P0002'; end if;
  return jsonb_build_object('customer',customer,'summary',public.dashboard_data(array[p_entity],p_from,p_as_of,now(),p_customer));
end $$;

create function public.document_detail(p_entity uuid,p_kind text,p_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare ws uuid; result jsonb;
begin
  ws:=public.authorize_report_entities(array[p_entity]);
  if p_kind='invoices' then
    if exists(select 1 from public.invoices where id=p_id and workspace_id=ws and entity_id=p_entity) then result:=public.invoice_payload(p_id); end if;
  elsif p_kind='challans' then
    if exists(select 1 from public.delivery_challans where id=p_id and workspace_id=ws and entity_id=p_entity) then result:=public.challan_payload(p_id); end if;
  else raise exception 'Invalid document type' using errcode='23514'; end if;
  if result is null then raise exception 'Document not found' using errcode='P0002'; end if;
  return result;
end $$;

-- Read payloads include all editable line data so a subsequent save preserves it.
alter function public.invoice_payload(uuid) rename to invoice_payload_base;
revoke all on function public.invoice_payload_base(uuid) from public,anon,authenticated;
create function public.invoice_payload(p_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
  select public.invoice_payload_base(p_id)||jsonb_build_object(
    'terms',b.terms,'placeOfSupplyStateCode',b.place_of_supply_state_code,'taxTreatment',b.tax_treatment,
    'lines',coalesce((select jsonb_agg(jsonb_build_object('id',i.sort_order,'databaseId',i.id,'description',i.particulars,
      'quantity',i.quantity::text,'rate',rtrim(rtrim(i.unit_rate::text,'0'),'.'),'style',i.style_number_snapshot,'styleId',i.style_id,
      'printType',i.print_type_snapshot,'placement',i.placement_snapshot,'unit',i.unit_snapshot,'unitCode',u.code,
      'discountCents',i.line_discount_amount*100,'adjustmentCents',i.line_adjustment_amount*100,'adjustmentReason',i.line_adjustment_reason,
      'placementDetail',i.placement_detail,'hsnSacCode',i.hsn_sac_code,'taxProfileId',i.tax_profile_id,
      'taxMode',i.tax_mode_snapshot,'cgstRate',i.cgst_rate,'sgstRate',i.sgst_rate,'igstRate',i.igst_rate,'otherTaxRate',i.other_tax_rate,
      'amountCents',i.line_total*100,'taxableCents',i.taxable_amount*100,'taxCents',i.tax_amount*100)
      order by i.sort_order) from public.invoice_items i join public.units u on u.id=i.unit_id where i.invoice_id=b.id),'[]'))
  from public.invoices b join public.workspaces w on w.id=b.workspace_id where b.id=p_id and w.owner_user_id=auth.uid()
$$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
    and p.proname in ('authorize_report_entities','list_documents','dashboard_data','customer_summary','document_detail','invoice_payload') loop
    execute format('revoke all on function %s from public,anon',f.signature);
    execute format('grant execute on function %s to authenticated',f.signature);
  end loop;
end $$;

create function public.delete_challan_draft(p_entity uuid,p_id uuid,p_version bigint) returns void
language plpgsql security definer set search_path='' as $$
declare ws uuid; d public.delivery_challans;
begin
  ws:=public.require_entity(p_entity);
  select * into strict d from public.delivery_challans where id=p_id and entity_id=p_entity and workspace_id=ws for update;
  if d.status<>'draft' or d.version<>p_version then raise exception 'Draft changed or already issued' using errcode='40001'; end if;
  delete from public.dc_items where dc_id=p_id;
  delete from public.delivery_challans where id=p_id;
end $$;

create function public.duplicate_invoice(p_entity uuid,p_id uuid,p_new_id uuid,p_date date) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; source public.invoices; payload jsonb; lines jsonb; result jsonb;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict source from public.invoices where id=p_id and entity_id=p_entity and workspace_id=ws for share;
  select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',i.sort_order,'description',i.particulars,
    'quantity',i.quantity::text,'rate',i.unit_rate::text,'style',i.style_number_snapshot,'printType',i.print_type_snapshot,
    'placement',i.placement_snapshot,'unitCode',u.code,'placementDetail',i.placement_detail,'hsnSacCode',i.hsn_sac_code,
    'discountCents',i.line_discount_amount*100,'adjustmentCents',i.line_adjustment_amount*100,'adjustmentReason',i.line_adjustment_reason,
    'taxProfileId',i.tax_profile_id)) order by i.sort_order) into lines
    from public.invoice_items i join public.units u on u.id=i.unit_id where i.invoice_id=p_id;
  payload:=jsonb_strip_nulls(jsonb_build_object('id',p_new_id,'customerId',source.customer_id,'date',p_date,
    'due',p_date+greatest(source.due_date-source.invoice_date,0),'reference',source.reference_number,'notes',source.notes,'terms',source.terms,
    'discountCents',source.invoice_discount_total*100,'lines',lines));
  if not exists(select 1 from public.invoice_items where invoice_id=p_id and tax_profile_id is not null) then
    payload:=payload||jsonb_build_object('taxBasisPoints',coalesce((select max(other_tax_rate)*100 from public.invoice_items where invoice_id=p_id),0));
  end if;
  result:=public.save_invoice_draft(p_entity,payload);
  return result;
end $$;

create function public.update_workspace(p_data jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws public.workspaces;
begin
  select * into strict ws from public.workspaces where owner_user_id=auth.uid() for update;
  if (p_data ? 'timezone') and not exists(select 1 from pg_timezone_names where name=p_data->>'timezone') then
    raise exception 'Unknown timezone' using errcode='23514';
  end if;
  if (p_data ? 'name') and coalesce(length(btrim(p_data->>'name')),0) not between 1 and 200 then raise exception 'Enter a workspace name' using errcode='23514'; end if;
  update public.workspaces set name=coalesce(btrim(p_data->>'name'),name),timezone=coalesce(p_data->>'timezone',timezone),updated_at=now()
    where id=ws.id returning * into ws;
  insert into public.audit_logs(workspace_id,actor_user_id,action,resource_type,resource_id,metadata_json)
    values(ws.id,auth.uid(),'settings_updated','workspaces',ws.id,p_data);
  return to_jsonb(ws);
end $$;

create function public.configure_catalog(p_entity uuid,p_table text,p_id uuid,p_version bigint,p_data jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; result jsonb; oldrow jsonb; record_id uuid:=coalesce(p_id,gen_random_uuid());
begin
  ws:=public.require_entity(p_entity,true);
  if p_table not in ('styles','print_types','placements','units','tax_profiles') then raise exception 'Unknown catalog' using errcode='23514'; end if;
  if p_id is not null then
    execute format('select to_jsonb(r) from public.%I r where id=$1 and workspace_id=$2 and entity_id=$3 for update',p_table)
      into oldrow using p_id,ws,p_entity;
    if oldrow is null then raise exception 'Catalog record not found' using errcode='P0002'; end if;
    if p_version is null or p_version<>(oldrow->>'version')::bigint then raise exception 'Catalog record changed. Reload it.' using errcode='40001'; end if;
  end if;
  if p_table='styles' then
    if p_id is null then raise exception 'Use style resolution to create a style' using errcode='23514'; end if;
    update public.styles set
      name=case when p_data ? 'name' then p_data->>'name' else name end,
      description=case when p_data ? 'description' then p_data->>'description' else description end,
      default_print_type_id=case when p_data ? 'defaultPrintTypeId' then (p_data->>'defaultPrintTypeId')::uuid else default_print_type_id end,
      default_placement_id=case when p_data ? 'defaultPlacementId' then (p_data->>'defaultPlacementId')::uuid else default_placement_id end,
      default_unit_id=case when p_data ? 'defaultUnitId' then (p_data->>'defaultUnitId')::uuid else default_unit_id end,
      is_active=coalesce((p_data->>'is_active')::boolean,is_active) where id=p_id returning to_jsonb(styles.*) into result;
  elsif p_table='tax_profiles' then
    if p_id is null then
      insert into public.tax_profiles(id,workspace_id,entity_id,name,tax_mode,cgst_rate,sgst_rate,igst_rate,other_tax_rate)
        values(record_id,ws,p_entity,p_data->>'name',p_data->>'tax_mode',coalesce((p_data->>'cgst_rate')::numeric,0),
        coalesce((p_data->>'sgst_rate')::numeric,0),coalesce((p_data->>'igst_rate')::numeric,0),coalesce((p_data->>'other_tax_rate')::numeric,0))
        returning to_jsonb(tax_profiles.*) into result;
    else
      update public.tax_profiles set name=coalesce(p_data->>'name',name),tax_mode=coalesce(p_data->>'tax_mode',tax_mode),
        cgst_rate=coalesce((p_data->>'cgst_rate')::numeric,cgst_rate),sgst_rate=coalesce((p_data->>'sgst_rate')::numeric,sgst_rate),
        igst_rate=coalesce((p_data->>'igst_rate')::numeric,igst_rate),other_tax_rate=coalesce((p_data->>'other_tax_rate')::numeric,other_tax_rate),
        is_active=coalesce((p_data->>'is_active')::boolean,is_active) where id=p_id returning to_jsonb(tax_profiles.*) into result;
    end if;
  elsif p_id is null then
    execute format('insert into public.%I(id,workspace_id,entity_id,code,label,sort_order) values($1,$2,$3,$4,$5,$6) returning to_jsonb(%I.*)',p_table,p_table)
      into result using record_id,ws,p_entity,upper(btrim(p_data->>'code')),btrim(p_data->>'label'),coalesce((p_data->>'sort_order')::integer,0);
  else
    execute format('update public.%I set label=coalesce($1,label),is_active=coalesce($2,is_active),sort_order=coalesce($3,sort_order) where id=$4 returning to_jsonb(%I.*)',p_table,p_table)
      into result using p_data->>'label',(p_data->>'is_active')::boolean,(p_data->>'sort_order')::integer,p_id;
  end if;
  return result;
end $$;

create function public.configure_entity(p_entity uuid,p_version bigint,p_data jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; e public.billing_entities;
begin
  ws:=public.require_entity(p_entity,true);
  select * into strict e from public.billing_entities where id=p_entity for update;
  if e.version<>p_version then raise exception 'Company settings changed' using errcode='40001'; end if;
  update public.billing_entities set
    default_tax_profile_id=case when p_data ? 'defaultTaxProfileId' then (p_data->>'defaultTaxProfileId')::uuid else default_tax_profile_id end,
    default_invoice_template_id=case when p_data ? 'defaultInvoiceTemplateId' then (p_data->>'defaultInvoiceTemplateId')::uuid else default_invoice_template_id end,
    default_dc_template_id=case when p_data ? 'defaultDcTemplateId' then (p_data->>'defaultDcTemplateId')::uuid else default_dc_template_id end,
    rounding_increment=coalesce((p_data->>'roundingIncrement')::numeric,rounding_increment),
    default_terms=case when p_data ? 'defaultTerms' then p_data->>'defaultTerms' else default_terms end
    where id=p_entity returning * into e;
  if e.default_tax_profile_id is not null and not exists(select 1 from public.tax_profiles where id=e.default_tax_profile_id and is_active) then
    raise exception 'Default tax profile is archived' using errcode='23514';
  end if;
  return to_jsonb(e);
end $$;

-- Validate monetary precision before casts into scale-constrained table columns.
alter function public.save_invoice_draft(uuid,jsonb) rename to save_invoice_draft_versioned;
revoke all on function public.save_invoice_draft_versioned(uuid,jsonb) from public,anon,authenticated;
create function public.save_invoice_draft(p_entity uuid,p_bill jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare item jsonb; key text; amount numeric; result jsonb; bid uuid:=(p_bill->>'id')::uuid;
begin
  perform public.require_entity(p_entity,true);
  if jsonb_typeof(p_bill->'lines') is distinct from 'array' or jsonb_array_length(p_bill->'lines') not between 1 and 100 then
    raise exception 'Add between 1 and 100 items' using errcode='23514';
  end if;
  if (p_bill ? 'taxBasisPoints') and ((p_bill->>'taxBasisPoints')::numeric<>trunc((p_bill->>'taxBasisPoints')::numeric)
    or (p_bill->>'taxBasisPoints')::numeric not between 0 and 10000) then raise exception 'Invalid tax rate precision' using errcode='23514'; end if;
  for item in select value from jsonb_array_elements(p_bill->'lines') loop
    foreach key in array array['discountCents','adjustmentCents'] loop
      if item ? key then
        amount:=(item->>key)::numeric;
        if amount is null or amount<>trunc(amount) or amount not between -9007199254740991 and 9007199254740991 then
          raise exception 'Use integer paise for adjustments and discounts' using errcode='23514';
        end if;
      end if;
    end loop;
    if nullif(item->>'taxProfileId','') is not null and p_bill ? 'taxBasisPoints' then
      raise exception 'Choose either per-line tax profiles or a bill-wide tax rate' using errcode='23514';
    end if;
  end loop;
  result:=public.save_invoice_draft_versioned(p_entity,p_bill);
  -- Updating only drafts also ensures an issuance retry never modifies issued snapshots.
  if exists(select 1 from public.invoices where id=bid and status='draft') then
    update public.invoices set place_of_supply_state_code=p_bill->>'placeOfSupplyStateCode',tax_treatment=p_bill->>'taxTreatment'
      where id=bid;
    update public.invoice_items i set hsn_sac_code=x.value->>'hsnSacCode'
      from jsonb_array_elements(p_bill->'lines') with ordinality x(value,n) where i.invoice_id=bid and i.sort_order=x.n;
    result:=public.invoice_payload(bid);
  end if;
  return result;
end $$;

-- Publication timestamps and acknowledgements are immutable evidence.
create or replace function public.guard_catalog_history() returns trigger language plpgsql set search_path='' as $$
begin
  if tg_op='DELETE' then raise exception 'Archive catalog records instead of deleting' using errcode='23514'; end if;
  if tg_table_name='document_templates' then
    if old.status='published' then raise exception 'Published templates are immutable' using errcode='23514'; end if;
  elsif tg_table_name='styles' then
    if new.style_number<>old.style_number and exists(select 1 from public.invoice_items i join public.invoices b on b.id=i.invoice_id
      where i.style_id=old.id and b.status<>'draft') then raise exception 'Issued style numbers are immutable' using errcode='23514'; end if;
  end if;
  return new;
end $$;

create function public.guard_append_only() returns trigger language plpgsql set search_path='' as $$
begin raise exception 'Historical evidence cannot be changed or deleted' using errcode='23514'; end $$;
create trigger audit_append_only before update or delete on public.audit_logs for each row execute function public.guard_append_only();
create trigger acknowledgement_append_only before update or delete on public.delivery_acknowledgements for each row execute function public.guard_append_only();

do $$
declare f record;
begin
  for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
    and p.proname in ('delete_challan_draft','duplicate_invoice','update_workspace','configure_catalog','configure_entity','save_invoice_draft') loop
    execute format('revoke all on function %s from public,anon',f.signature);
    execute format('grant execute on function %s to authenticated',f.signature);
  end loop;
end $$;
revoke all on function public.guard_append_only() from public,anon,authenticated;

create function public.preview_invoice(p_entity uuid,p_bill jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
  -- Exception subtransactions undo every catalog/draft/audit write while retaining local variables.
  begin
    result:=public.save_invoice_draft(p_entity,p_bill);
    raise exception using errcode='ZP001',message='Preview complete';
  exception when sqlstate 'ZP001' then null;
  end;
  return result;
end $$;
revoke all on function public.preview_invoice(uuid,jsonb) from public,anon;
grant execute on function public.preview_invoice(uuid,jsonb) to authenticated;

create function public.archive_directory_record(p_entity uuid,p_table text,p_id uuid,p_version bigint,p_active boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; result jsonb; current_version bigint;
begin
  ws:=public.require_entity(p_entity);
  if p_table='billing_entities' and p_id=p_entity then
    select version into current_version from public.billing_entities where id=p_id and workspace_id=ws for update;
    if current_version is distinct from p_version then raise exception 'Company changed. Reload it.' using errcode='40001'; end if;
    update public.billing_entities set is_active=p_active where id=p_id returning to_jsonb(billing_entities.*) into result;
  elsif p_table='customers' then
    select version into current_version from public.customers where id=p_id and workspace_id=ws and entity_id=p_entity for update;
    if current_version is null then raise exception 'Customer not found' using errcode='P0002'; end if;
    if current_version<>p_version then raise exception 'Customer changed. Reload it.' using errcode='40001'; end if;
    update public.customers set is_active=p_active where id=p_id returning to_jsonb(customers.*) into result;
  else raise exception 'Invalid directory operation' using errcode='23514'; end if;
  return result;
end $$;
revoke all on function public.archive_directory_record(uuid,text,uuid,bigint,boolean) from public,anon;
grant execute on function public.archive_directory_record(uuid,text,uuid,bigint,boolean) to authenticated;

create function public.filtered_report_data(p_entities uuid[],p_type text,p_from date,p_as_of date,p_recorded_through timestamptz default now(),p_customer uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ws uuid; zone text; boundary timestamptz; headers jsonb; rows jsonb; summary jsonb;
begin
  ws:=public.authorize_report_entities(p_entities);
  select timezone into zone from public.workspaces where id=ws;
  if p_from is null or p_as_of is null or p_from>p_as_of or p_as_of-p_from>3660 or p_recorded_through is null or p_recorded_through>clock_timestamp() then
    raise exception 'Use a valid report period up to ten years' using errcode='23514';
  end if;
  if p_customer is not null and not exists(select 1 from public.customers where id=p_customer and workspace_id=ws and entity_id=any(p_entities)) then
    raise exception 'Customer not found' using errcode='42501';
  end if;
  boundary:=(p_as_of+1)::timestamp at time zone zone;
  if p_type in ('customers','companies') then
    summary:=public.dashboard_data(p_entities,p_from,p_as_of,p_recorded_through,p_customer);
    if p_type='companies' then
      headers:='["Company","Billed","Collected","Outstanding","Invoice count"]';
      select coalesce(jsonb_agg(jsonb_build_array(x->>'name',(x->>'billed')::numeric,(x->>'collected')::numeric,
        (x->>'outstanding')::numeric,(x->>'invoiceCount')::bigint)),'[]') into rows from jsonb_array_elements(summary->'entities') x;
    else
      headers:='["Company","Customer","Invoice count","Billed","Collected","Outstanding","Latest invoice"]';
      with eligible as (
        select b.*,coalesce((select sum(p.amount) from public.payments p where p.invoice_id=b.id and p.payment_date<=p_as_of and p.posted_at<=p_recorded_through
          and not coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false)),0) paid
        from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and b.invoice_date<=p_as_of and b.issued_at<=p_recorded_through
          and (p_customer is null or b.customer_id=p_customer) and not coalesce(b.cancelled_at<boundary and b.cancelled_at<=p_recorded_through,false)
      ), customers as (
        select b.entity_id,b.customer_id,max(b.seller_snapshot->>'legal_name') company,max(b.customer_snapshot->>'legal_name') customer,
          count(*) filter(where b.invoice_date>=p_from) n,coalesce(sum(b.grand_total) filter(where b.invoice_date>=p_from),0) billed,
          sum(b.grand_total-b.paid) outstanding,max(b.invoice_date) latest from eligible b group by b.entity_id,b.customer_id
      ) select coalesce(jsonb_agg(jsonb_build_array(c.company,c.customer,c.n,c.billed,
        coalesce((select sum(p.amount) from public.payments p join public.invoices b on b.id=p.invoice_id
          where b.entity_id=c.entity_id and b.customer_id=c.customer_id and p.payment_date between p_from and p_as_of and p.posted_at<=p_recorded_through
            and not coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false)),0),c.outstanding,c.latest)
        order by c.billed desc,c.entity_id,c.customer_id),'[]') into rows from customers c;
    end if;
    return jsonb_build_object('headers',headers,'rows',rows,'from',p_from,'asOf',p_as_of,'recordedThrough',p_recorded_through,
      'timezone',zone,'definitionVersion','v2','customerId',p_customer);
  end if;
  if p_type='challans' then
    headers:='["Challan","Recipient","Date","Items"]';
    select coalesce(jsonb_agg(jsonb_build_array(d.document_number,d.recipient_name,d.dc_date,
      (select string_agg(i.particulars,', ' order by i.sort_order) from public.dc_items i where i.dc_id=d.id)) order by d.dc_date,d.id),'[]') into rows
    from public.delivery_challans d where d.workspace_id=ws and d.entity_id=any(p_entities) and (p_customer is null or d.customer_id=p_customer) and d.dc_date between p_from and p_as_of
      and d.issued_at<=p_recorded_through and not(coalesce(d.cancelled_at<boundary and d.cancelled_at<=p_recorded_through,false));
  elsif p_type='cancelled' then
    headers:='["Bill","Customer","Cancelled on","Reason","Original amount"]';
    select coalesce(jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.cancelled_at,b.cancel_reason,b.grand_total) order by b.cancelled_at,b.id),'[]') into rows
    from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and (p_customer is null or b.customer_id=p_customer) and b.cancelled_at<=p_recorded_through
      and (b.cancelled_at at time zone zone)::date between p_from and p_as_of;
  elsif p_type='collections' then
    headers:='["Bill","Date","Method","Amount"]';
    select coalesce(jsonb_agg(jsonb_build_array(b.document_number,p.payment_date,p.method,p.amount) order by p.payment_date,p.id),'[]') into rows
    from public.payments p join public.invoices b on b.id=p.invoice_id
    where p.workspace_id=ws and p.entity_id=any(p_entities) and (p_customer is null or b.customer_id=p_customer) and p.payment_date between p_from and p_as_of
      and p.posted_at<=p_recorded_through and not(coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false));
  elsif p_type in ('billing','outstanding','customers','monthly','print-type','companies') then
    with eligible as (
      select b.*,
        coalesce((select sum(p.amount) from public.payments p where p.invoice_id=b.id and p.payment_date<=p_as_of and p.posted_at<=p_recorded_through
          and not(coalesce(p.reversed_at<boundary and p.reversed_at<=p_recorded_through,false))),0) paid
      from public.invoices b where b.workspace_id=ws and b.entity_id=any(p_entities) and (p_customer is null or b.customer_id=p_customer) and b.invoice_date<=p_as_of and b.issued_at<=p_recorded_through
        and not(coalesce(b.cancelled_at<boundary and b.cancelled_at<=p_recorded_through,false))
    ), grouped as (
      select case when p_type='customers' then b.entity_id::text||':'||b.customer_id::text when p_type='monthly' then to_char(b.invoice_date,'YYYY-MM')
        else b.entity_id::text end grouping_key,
        min(case when p_type='customers' then (b.seller_snapshot->>'legal_name')||' · '||(b.customer_snapshot->>'legal_name')
          when p_type='monthly' then to_char(b.invoice_date,'YYYY-MM') else b.seller_snapshot->>'legal_name' end) label,
        sum(b.grand_total) total
      from eligible b where b.invoice_date>=p_from group by 1
    ), print_groups as (
      select coalesce(i.print_type_snapshot,'Unspecified') label,sum(i.line_total) total
        from eligible b join public.invoice_items i on i.invoice_id=b.id where b.invoice_date>=p_from group by 1
      union all
      select 'Round off',sum(b.round_off) from eligible b where b.invoice_date>=p_from having sum(b.round_off)<>0
    )
    select case when p_type='billing' then coalesce((select jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.invoice_date,b.grand_total) order by b.invoice_date,b.id) from eligible b where b.invoice_date>=p_from),'[]')
      when p_type='outstanding' then coalesce((select jsonb_agg(jsonb_build_array(b.document_number,b.customer_snapshot->>'legal_name',b.due_date,b.grand_total-b.paid) order by b.due_date,b.id) from eligible b where b.grand_total>b.paid),'[]')
      when p_type='print-type' then coalesce((select jsonb_agg(jsonb_build_array(label,total) order by label) from print_groups),'[]')
      else coalesce((select jsonb_agg(jsonb_build_array(label,total) order by label) from grouped),'[]') end into rows;
    headers:=case when p_type='billing' then '["Bill","Customer","Date","Amount"]'::jsonb
      when p_type='outstanding' then '["Bill","Customer","Due date","Outstanding"]'::jsonb
      else '["Group","Amount"]'::jsonb end;
  else raise exception 'Unknown report' using errcode='23514'; end if;
  return jsonb_build_object('headers',headers,'rows',rows,'from',p_from,'asOf',p_as_of,'recordedThrough',p_recorded_through,'timezone',zone,'definitionVersion','v2','customerId',p_customer);
end $$;

create function public.request_filtered_export(p_entities uuid[],p_type text,p_from date,p_as_of date,p_format text,p_customer uuid default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare dataset jsonb; ws uuid; result public.report_exports; names jsonb;
begin
  dataset:=public.filtered_report_data(p_entities,p_type,p_from,p_as_of,clock_timestamp(),p_customer);
  select id into strict ws from public.workspaces where owner_user_id=auth.uid();
  select jsonb_agg(jsonb_build_object('id',id,'name',legal_name) order by legal_name) into names from public.billing_entities where id=any(p_entities) and workspace_id=ws;
  insert into public.report_exports(workspace_id,requested_by,report_type,entity_ids,filters_json,as_of_date,recorded_through,business_timezone,
    title_snapshot,entity_names_snapshot,format,data_snapshot,expires_at,report_definition_version)
    values(ws,auth.uid(),p_type,p_entities,jsonb_build_object('from',p_from,'asOf',p_as_of,'customerId',p_customer),p_as_of,(dataset->>'recordedThrough')::timestamptz,
      dataset->>'timezone',initcap(replace(p_type,'-',' '))||' report',names,p_format,dataset,clock_timestamp()+interval '7 days','v2') returning * into result;
  insert into public.audit_logs(workspace_id,actor_user_id,action,resource_type,resource_id,metadata_json)
    values(ws,auth.uid(),'export_requested','report_exports',result.id,jsonb_build_object('type',p_type,'entities',p_entities));
  return to_jsonb(result);
end $$;


revoke all on function public.filtered_report_data(uuid[],text,date,date,timestamptz,uuid),public.request_filtered_export(uuid[],text,date,date,text,uuid) from public,anon;
grant execute on function public.filtered_report_data(uuid[],text,date,date,timestamptz,uuid),public.request_filtered_export(uuid[],text,date,date,text,uuid) to authenticated;

-- Preserve cancelled/original file identities and allow failed work to be retried explicitly.
create function public.retry_document_file(p_entity uuid,p_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ws uuid; f public.document_files;
begin
  ws:=public.require_entity(p_entity);
  select * into strict f from public.document_files where id=p_id and workspace_id=ws and entity_id=p_entity for update;
  if f.status='ready' then return to_jsonb(f); end if;
  if f.status='processing' and f.lease_expires_at>clock_timestamp() then raise exception 'Document generation is running' using errcode='55P03'; end if;
  update public.document_files set status='pending',claim_token=null,lease_expires_at=null,next_attempt_at=clock_timestamp(),last_error=null,updated_at=now()
    where id=p_id returning * into f;
  return to_jsonb(f);
end $$;

create function public.retry_report_export(p_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare f public.report_exports;
begin
  select r.* into strict f from public.report_exports r join public.workspaces w on w.id=r.workspace_id
    where r.id=p_id and w.owner_user_id=auth.uid() for update of r;
  if f.expires_at<=clock_timestamp() then raise exception 'Export expired. Request a new report.' using errcode='23514'; end if;
  if f.status='ready' then return jsonb_build_object('id',f.id,'status',f.status); end if;
  if f.status='processing' and f.lease_expires_at>clock_timestamp() then raise exception 'Export generation is running' using errcode='55P03'; end if;
  update public.report_exports set status='pending',claim_token=null,lease_expires_at=null,next_attempt_at=clock_timestamp(),last_error=null,updated_at=now() where id=p_id;
  return jsonb_build_object('id',f.id,'status','pending');
end $$;

-- A finished file can be written only by the current, unexpired claim.
create or replace function public.finish_document_file(p_entity uuid,p_id uuid,p_token uuid,p_result jsonb) returns void language plpgsql security definer set search_path='' as $$
declare ws uuid; prefix text;
begin
  ws:=public.require_entity(p_entity);prefix:=ws::text||'/'||p_entity::text||'/';
  if p_result ? 'path' and left(p_result->>'path',length(prefix))<>prefix then raise exception 'Invalid storage path' using errcode='42501'; end if;
  if not(p_result ? 'error') and (p_result->>'sha256' is null or p_result->>'sha256' !~ '^[0-9a-f]{64}$') then raise exception 'Invalid file checksum' using errcode='23514'; end if;
  update public.document_files set status=case when p_result ? 'error' then 'failed' else 'ready' end,
    object_path=p_result->>'path',sha256=p_result->>'sha256',byte_size=(p_result->>'size')::bigint,
    last_error=left(p_result->>'error',2000),generated_at=case when not(p_result ? 'error') then clock_timestamp() end,
    lease_expires_at=null,updated_at=now() where id=p_id and workspace_id=ws and entity_id=p_entity and claim_token=p_token
      and status='processing' and lease_expires_at>clock_timestamp();
  if not found then raise exception 'PDF claim expired' using errcode='40001'; end if;
end $$;

create function public.validate_catalog_defaults() returns trigger language plpgsql set search_path='' as $$
begin
  if new.is_active then
    if new.default_print_type_id is not null and not exists(select 1 from public.print_types where id=new.default_print_type_id and is_active) then
      raise exception 'Style default print type is archived' using errcode='23514'; end if;
    if new.default_placement_id is not null and not exists(select 1 from public.placements where id=new.default_placement_id and is_active) then
      raise exception 'Style default placement is archived' using errcode='23514'; end if;
    if new.default_unit_id is not null and not exists(select 1 from public.units where id=new.default_unit_id and is_active) then
      raise exception 'Style default unit is archived' using errcode='23514'; end if;
  end if;
